// Файл згенеровано scripts/build_tlumach.py з scripts/zigaben/uk/, не правте вручну.
import type { TlumPsalms } from './index';
// Кафизма 1: псалми 1–8.
export const Z: TlumPsalms = {"1":[{"v":"1","t":["Блаженний, власне, Бог, як каже Павло, що називає Його «блаженним і єдиним сильним» (1Тим. 6:15). Але, як і багато інших імен, ця назва з поблажливості приписується й нам, як і Богу, бо сказано: «Я сказав: ви — боги» (Пс. 81:6). Ім’я ж блаженного є плодом досконалості в чесноті. Воно означає (мається на увазі μακάριος) «безсмертного», тобто вільного від усякої смерті (κήρ), з додаванням літери μ (Зигабен грає тут грецьким словом μακάριος, виводячи його від κήρ — смерть, мука — і заперечної частки α, «не», а літеру μ вважаючи ніби приставною. — Прим. ред.). Вислів «блаженний» охоплює й жіночий рід, як частину, що належить до цілого. «Бо чоловік — голова жінки» (Еф. 5:23), за божественним апостолом, а з головою з’єднуються й члени тіла. І як цим останнім спільна людська природа, так їм (чоловікові й жінці) спільні й діла, і нагорода. Відповідно до природи речей Давид зберіг такий самий порядок і в словах. Рада, тобто бажання. Бо корінь дій, що їх чинить тіло, — бажання серця, як і Господь каже, що те, що всередині, оскверняє людину (Мф. 15:18). Спершу ми радимося, потім утверджуємо раду, а наостанок чинимо за порадженим. Нечестивим називається безбожник або багатобожник, а грішником — хоч і віруючий (εὐσεβής), але той, хто веде беззаконне й розпусне життя; губитель же — той, хто не лише сам грішить, а й інших розбещує і заражає «своєю» недугою. Давид ублажає того, хто віддалився від таких людей і не спілкувався з нечестивими в раді проти істинного Бога навіть мимохідь (μηδ’ ὅσον ἐν παρόδῳ); бо таке значення, гадаю, має тут «ходіння» («не ходить»). Далі ублажає того, хто не стояв із грішниками в злі, хоч би й був якось захоплений у гріх, і не віддається, подібно до губителів, такій самій пристрасті, бо це й означає слово «на сидінні». Можна й інакше: під радою нечестивих розуміти їхнє зібрання, як переклали Акила й Феодотіон; під путтю грішних — диявола, бо хто не стоїть у дияволі, той приходить до Бога, Який сказав: «Я є путь» (Ін. 14:6), якою люди проходять до чесноти; під сидінням — учення лукавих. А що для звершення чесноти недостатньо віддалення від зла, то він каже: «Ухилися від зла і чини добро» (Пс. 36:27), і Ісая навчає: «Перестаньте чинити лукавство ваше, навчіться робити добро» (Іс. 1:16–17). Так і тут дуже послідовно (псалмоспівець) додав:"],"h":"Блаженний муж, що не ходить на раду нечестивих, і на путі грішних не стоїть, і на сидінні губителів не сидить"},{"v":"2","t":["Він каже: блаженний не лише той, хто не брав участі ні в чому з вищесказаного, а й той, хто погоджував свою волю із законом Господнім, бажаючи (лише) того й постійно роздумуючи про те, чого навчає закон, і відповідно до цього влаштовував своє життя. Бо так і Бог узаконив через Мойсея, кажучи: «І хай будуть слова цього закону завжди в устах твоїх, і роздумуватимеш про них, сидячи й устаючи, і лягаючи спати, і прив’яжеш їх на руці твоїй, і будуть непорушними перед очима твоїми» (Втор. 6:6, не дослівно). Потім показує плід, що звідси народжується:"],"h":"Але в законі Господнім воля його, і в законі Його повчатиметься день і ніч"},{"v":"3","t":["Бо хто так поводиться, той, наче посаджений при потоці божественних слів і напоюваний їхнім ученням, зеленіє й росте і, подібно до дерева, посадженого при джерелі вод, приносить плід — чесноти в належний час — і не скидає листя, тобто (не полишає) смиренномудрості, що вкриває й оберігає чесноти. Або під плодом слід розуміти духовне багатство, що збирається від трудів, а під листям — зігрівальну надію спасіння, якої ніколи не втрачають і яка полегшує відчуття скорбот. Слушно ж божественні слова порівнюють із водами, бо вони напоюють і роблять плідними душі, як води — рослини. Так і Христос назвав Своє власне вчення, сказавши: «Хто спраглий, нехай прийде до Мене і п’є; і: хто вірує в Мене, з утроби того потечуть ріки води живої» (Ін. 7:37–38); і: «Хто питиме воду, яку Я дам йому, не матиме спраги повіки» (Ін. 4:14). Такій людині і Бог сприяє в усьому. «Бо від Господа, сказано, стопи людини виправляються, і путь його Він уподобає дуже» (Пс. 36:23). І апостол знову каже: «Тим, хто любить Бога, усе сприяє на добре» (Рим. 8:28). Вислів «усе» додано обґрунтовано, бо той, хто досяг успіху в цьому, і не бажає зробити щось лихе, тому він і отримує від Бога успіх в усьому. Отже, спонукавши до чесноти (обітницею) благ, він укріплює подвижників указанням на нещастя, коли каже:"],"h":"І буде, як дерево, посаджене при витоках вод, що плід свій дасть у час свій, і лист його не опаде, і все, що він чинить, матиме успіх"},{"v":"4","t":["Тобто вони не ростуть і не приносять плоду, як вищезгаданий чоловік, і не насолоджуються іншими благами. Подвоєнням заперечення він утвердив заборону."],"h":"Не так нечестиві, не так"},{"v":"4","t":["Як налетілий вітер здіймає порох і розвіює його, так і супротивні демони (розносять) нечестивих. Лицем же землі слід вважати її поверхню. Вона ж називається і хребтом (νῶτα), бо обтяжена тілами, що на ній перебувають. Подібно й надрами землі називається її глибина; нечестивими ж він тут називає всіх вищезгаданих, узагальнюючи сказане раніше. Під нечестивими можна розуміти юдеїв, які за неповагу до Сина розвіяні подихом проповіді святих апостолів."],"h":"Але як порох, що його змітає вітер з лиця землі"},{"v":"5","t":["Дивись, з якою дбайливістю говорить Божественний Дух: не сказав просто «не воскреснуть», а додав: «на суд». Бо воскреснуть і вони, але не для того, щоб бути судженими, — бо як судити тих, хто вже засуджений? «Хто не вірує в Мене, — каже Він, — той уже засуджений» (Ін. 3:18); але (воскреснуть), щоб зазнати покарань. Слід звернути увагу й на те, що Мойсей нічого не сказав про воскресіння, і першим почав навчати про нього Давид."],"h":"Через те не воскреснуть нечестиві на суд"},{"v":"5","t":["Грішниками в цьому місці називає не взагалі нечестивих, а розпусних і злих, які одні будуть суджені й далеко відіслані від праведних. Бо «раду» Акила й Феодотіон переклали як «зібрання» праведних. Праведними ж у божественному Писанні зазвичай називаються не лише ті, хто власною чеснотою досяг праведності, а й узагалі всі святі, як виправдані Богом."],"h":"Ані грішні — у раду праведних"},{"v":"6","t":["Показує, що ніхто не сховається від Бога. Бо й путі праведних Він знає, як сказано: «Знає Господь дні непорочних» (Пс. 36:18), і знову: «Пізнав Господь Своїх» (2Тим. 2:19). А що Він і Сам сказав: «Я є путь», то неодмінно Він знає й тих, хто ходить нею, тобто Його заповідями. Щодо ж злих, як недостойних Його знання, Він удає, ніби не знає, тому й Адама, що згрішив, питав: «Де ти?» Так само чинив і щодо Каїна та багатьох інших (Бут. 3:9; Бут. 4:9)."],"h":"Бо знає Господь путь праведних"},{"v":"6","t":["Чесноти праведних залишаються, як їхнє багатство й вінець. А діла й лукавство нечестивих, які він тепер назвав путтю, зникають і стають безсилими. З цим схоже й апостольське слово: «А в кого діло згорить, той зазнає втрати» (1Кор. 3:15)."],"h":"А путь нечестивих загине"}],"2":[{"v":"0","t":["Цей другий псалом (як і перший) не має надписання в єврейському тексті; зміст же його такий: у ньому провіщаються підступні задуми ворогів Господа й Христа Його, потім — покликання язичників і відкинення юдеїв."]},{"v":"1-2","t":["Передбачаючи пророчим зором їхню несамовитість і лютість, Давид зі скорботою й сльозами так починає свій псалом: горе! навіщо вони з таким безумством метушаться, зчинили таку тривогу й замишляють усе повалити? Під язичниками («народи») тут розуміються римські воїни разом із Пилатом, а під людьми — юдейський народ з Анною та Каяфою; під іменем же царів («царі земні») і верховних правителів, або архонтів («князі»), — Ірод і Пилат, з яких перший був царем, а другий правителем, як розповідається про це, з поясненням самого тексту, у книзі Діянь Апостольських (Діян. 4:6, 25–27; пор. Лк. 23:1–15; Ін. 18:12–14, 27; Мф. 14:9; Мф. 27:2; Мк. 6:14, 22, 25–27). А те, що «царі» й «князі» сказано в множині замість однини, пояснюють властивістю єврейської мови, яка допускає такий ужиток, або ж бачать у цьому інший, таємничий зміст, а саме: з іменем царя Ірода поєднують іншого царя — гріха, диявола, що озброївся проти Христа, а з князем Пилатом — багатьох князів, тобто «начала і влади темряви віку цього, духів злоби піднебесних», проти яких, за апостолом, нам належить вести «боротьбу» (Еф. 2:2; Еф. 6:12; Ін. 12:31; Ін. 14:30; Ін. 16:11). Бо оскільки в Христі (Богочоловікові) дві природи, невидима (божественна) і видима (людська), то Йому належало вести й подвійну боротьбу — з невидимими й видимими ворогами. Слова ж «задумали марне» (κενὰ ἐμελέτησαν — замишляють пусте) сказано замість «намагаються даремно» (μάτην ἐσπούδασαν), бо уявляють, що можуть погубити Того, Хто воскрес і живе повіки; і ці слова стосуються лише юдеїв, які, «спочиваючи на законі» Писань (Рим. 2:17), марно в них повчалися, не вникаючи й не розуміючи, що саме ці «Писання свідчать про Нього» (Ін. 5:39). «На Господа і на Христа Його» — тобто збурилися, повстали й радяться не менше проти Отця, ніж проти Сина Його, Якого Він поставив Царем над усіма народами, давши їх Йому в спадщину як Своєму Помазаникові. Ця війна проти Сина торкнулася й Отця. Отже, в цьому місці під «Господом» слід розуміти Бога Отця, а під «Христом» — Бога Сина. Бо Сам Отець, за Своїм Божественним домобудівництвом, поставив над ними царем Сина Свого. Якщо ж в останніх словах тексту «на Христа Його» (αὐτοῦ) допустити читання «на Христа їхнього» (αὐτῶν), множину замість однини, як це трапляється в багатьох списках Псалтиря, то й думку, що виражає це відношення, треба розширити й поширити на всіх — не лише юдеїв і язичників, а навіть і на самих занепалих духів, як сказано про Нього: «щоб перед ім’ям Його схилилося кожне коліно небесних, земних і підземних» (Флп. 2:9–11)."],"h":"Навіщо заметушилися народи, і люди задумали марне? Стали царі земні, і князі зібралися разом на Господа і на Христа Його"},{"v":"3","t":["Ці слова сказано або від імені Святого Духа, Який заповідає віруючим нащадкам відступити від ідолопоклонства язичників і від нечестя юдеїв, «розірвавши пута» рабства перших, якими вони були зв’язані, і «скинувши з себе ярмо» других, яким вони під законом обтяжувалися, як нестерпним і вбивчим тягарем, а натомість прийняти на себе «ярмо» і «тягар» Христів, «благий» і «легкий», що тяжкість закону й самі пута рабства розчиняє любов’ю і животворить (Мф. 11:30; 1Ін. 5:3). Або ж сказано їх (що вірніше відповідає самому зв’язку мови) від імені тих, хто, збурившись і словом, і ділом, розіп’яв Христа на хресті, скинув із себе ярмо послуху Синові й розірвав пута всякої покори Отцю, якими були зв’язані за самим законом природи."],"h":"Розірвімо пута їхні, і скиньмо з себе ярмо їхнє"},{"v":"4","t":["Тут богохульники ніби зупиняються в своєму богохульстві тим, що Отець, Який живе на небесах, і Син, Господь усього, за Своїм Божеством, постають такими, що сміються й глузують з них. Мова набуває посиленого тону, щоб показати їм і переконати їх, наскільки безрозсудні вони були, коли посягали на марне й неможливе, думаючи навіть Самого Господа, джерело й початок вічного життя (Ін. 3:16; Ін. 5:26; Ін. 20:31), умертвити, і що язичники вибрали собі замість Бога демонів, а юдеї вдовольнилися замість істини примарою."],"h":"Той, Хто живе на небесах, посміється з них, і Господь поглумиться з них"},{"v":"5","t":["Тоді вже, зрозуміло, заговорив до них Господь, коли Христос явно викрив юдеїв у їхніх неправдах і сповістив їм майбутні лиха, що мали їх спіткати, повторюючи, перелічуючи ці неправди й лиха, щоразу слова: «Горе вам, книжники і фарисеї, лицеміри» тощо; а наостанок додав: «Тому відніметься від вас Царство Боже» (Мф. 21:43; 23)."],"h":"Тоді заговорить до них у гніві Своєму"},{"v":"5","t":["Указуючи з обуренням на їхню крайню розбещеність і відкриваючи перед ними згубні наслідки, яких вони неминуче мають зазнати, Він приводить їх у збентеження й страх від непевності різних здогадів, бо багато хто з них вважав Його (Христа) пророком. Інші ж саме тут розуміють той бідний стан, що загрожував їм облогою й поневоленням від римлян. А ще інші відносять це до майбутнього суду, коли Верховний Суддя за тяжкі гріхи піддасть їх і тяжким покаранням. Слова «гнів» і «лють» іноді мають тотожне значення, а іноді відрізняються більшою чи меншою мірою свого значення, так що лють виражає вищий ступінь гніву, ніби несамовитість."],"h":"І люттю Своєю збентежить їх"},{"v":"6","t":["Далі йде мова від імені Христа; бо така властивість пророцтв, що в них змінюються і предмети, і особи, як це часто можна зустріти в пророків, які пророкували не з власної волі, а з натхнення Святого Духа, виконуючи своє служіння не інакше, як живі знаряддя (2Пет. 1:21). Провіщає ж Христос царство, передане Йому Отцем як людині; про що Він і засвідчив після Свого воскресіння, кажучи: «Дана Мені всяка влада на небі й на землі» (Мф. 28:18)."],"h":"Я ж поставлений Царем від Нього"},{"v":"6","t":["Під горою, що зветься Сіоном, розуміється вся Юдея, і слова тексту набувають такого змісту: Я поставлений Царем сповіщати євангельські заповіді на горі Сіоні, тобто в Єрусалимі. «Повелінням» же Господнім (πρόσταγμα — правило, настанова, вчення) називає самі ці заповіді, показуючи цим єдність Своєї волі з волею Отця. «Я нічого не можу творити Сам від Себе, — казав Він, проповідуючи на землі євангельське вчення, — як чую, так і суджу, і суд Мій праведний, бо не шукаю волі Моєї, а волі Отця, Який послав Мене. Я не від Себе говорив, але Отець, Який послав Мене, Він дав Мені заповідь, що сказати й що говорити. Я і Отець — одне» (Ін. 5:30; Ін. 10:30; Ін. 12:49)."],"h":"Над Сіоном, горою святою Його, сповіщаючи повеління Господнє"},{"v":"7","t":["Під цими словами тут розуміється і передвічне народження Бога Сина від Бога Отця, і божественне домобудівництво Його втілення в часі. Словом «сьогодні» виражається ніби межа між вічністю й часом, коли передвічний Син Божий став Богочоловіком, «призначений ще перед створенням світу, а з’явився в останні часи, коли настала повнота часу» (1Пет. 1:20; Гал. 4:4); а словом «породив» позначається саме звершення домобудівництва Його втілення. Бо Бог Отець називається Творцем і Будівничим усього."],"h":"Господь сказав до Мене: Ти Син Мій, Я сьогодні породив Тебе"},{"v":"8","t":["Христос за плоттю належав до роду юдеїв і тому найперше звернувся з проповіддю благовістя до них, як до Своїх одноплемінників; та коли вони не прийняли Його, Він природно звернувся потім до язичницьких племен, спонуканий до того й волею Отця, щоб обрав Собі язичників у спадщину. І справді, Синові Божому, як Тому, Хто «став причасником плоті й крові» людської (Євр. 2:14), годилося взяти участь і в людстві взагалі."],"h":"Проси в Мене, і дам Тобі народи — спадщину Твою"},{"v":"8","t":["Тобто й влада Твоєї спадщини простягнеться до меж землі. Так воно й збулося, бо Слово Євангелія рознеслося по всій землі й до всіх кінців вселенної (Пс. 18:5; Мф. 10:18; Мф. 24:14). І Сам Отець пропонує Синові просити Собі цієї спадщини, виявляючи Своє благовоління й бажання відновити все занепале людство. І Син природно клопочеться про це перед Отцем, бо Він заради нас, людей, і заради нашого спасіння вочоловічився і, ставши Богочоловіком, зробився Посередником між Богом і людьми. Отже, хай засоромляться й осоромляться юдеї, які не знаходять особи, до якої можна було б застосувати ці слова. Бо хто, крім Христа, здобув таку могутню владу?"],"h":"І володіння Твоє — кінці землі"},{"v":"9","t":["Здебільшого вважають, що пророк-псалмоспівець має тут на увазі юдеїв, ніби кажучи так: тих, хто не прийняв Твоєї проповіді, Ти розіб’єш жезлом залізним, як посуд гончаря, — позначаючи цим поневолення їх і панування над ними римлян. Бо коли юдеї відкинули царство Христове й визнали над собою царем кесаря (Ін. 19:15), то тим самим утвердили його владу, від якої й загинули. «Залізним» же названо його жезл через нестерпну його тяжкість; у такому значенні вживається це слово в Апокаліпсисі (Одкр. 19:15) і у видіннях пророка Даниїла. Інші ж гадають, що тут говориться про спасіння язичників, тлумачачи цей текст так: «пасти будеш їх» жезлом залізним — те саме, що покараєш, приборкаєш, напоумиш їх Своєю всемогутньою силою; і як гончар, побачивши, що виріб йому не вдався, розбиває його й перепалює у вогні, щоб зробити з нього ж нову посудину, так і Ти, Господи, зруйнуєш мудрування язичників Своїм благовістям, а потім купіллю відродження оновиш їх, зігрівши божественним теплом любові їхні серця в Дусі Святому."],"h":"Пасти будеш їх жезлом залізним, як посуд гончарський, розіб’єш їх"},{"v":"10","t":["Вислів «нині» має тут значення підсумкової частки, ніби сказано: отже, ви, могутні царі римлян та інших народів, і ви, судді всієї землі, що судите людей, які живуть на землі, — навчені досвідом, яких лих зазнали ті, хто безрозсудно відкинув Христа, і знаючи, що Він вибрав вас Собі в спадщину, — усі ви, кажу, схаменіться, відкинувши колишнє своє безумство, і станьте мудрими для спасіння, керуючись і досвідом, і Божественними Писаннями. А в особі головних представників, до яких звертається пророк, він розуміє й усіх їм підлеглих."],"h":"І нині, царі, зрозумійте, навчіться, усі, хто судить землю"},{"v":"11","t":["Оскільки ви вже знаєте й розумієте, — каже він їм далі, — що Христос є і Бог, і праведний, невсипущий Суддя й Відплатник, і що ви, як Його надбання, вшановані званням Його спадкоємців, то вам залишається тепер, приборкавши свої пристрасті й привівши до належного ладу свій спосіб життя, служити Йому зі страхом, як Господу: бо де страх Божий, там і виконання Його заповідей. «І радійте Йому з трепетом». І, служачи, радійте Йому, як своєму Спасителеві й Заступникові. Так і апостол каже: «Радійте в Господі; і знову кажу: радійте» (Флп. 4:4); проте ця ваша радість хай буде не без трепету. Радійте з надією і разом тремтіть за гріхи, бо суд Його праведний і нелицемірний, і ніхто від нього не сховається."],"h":"Служіть Господу зі страхом"},{"v":"12","t":["Цими словами пророк посилює те, що сказав вище, у 10-му вірші: схаменіться, станьте мудрими не будь-як, а цілковито й остаточно, — висловлюючись тут метафорично, ніби міцно тримаючи щось у стиснутому кулаці."],"h":"Прийміть настанову"},{"v":"12","t":["Путтю праведною називає певний спосіб життя праведних; бо в євреїв «путь» має різні значення, залежно від того, якою путтю хто ходить."],"h":"Щоб не розгнівався Господь, і не загинули ви з путі праведної"},{"v":"12","t":["Цим указує на день суду. До того ж висловом «незабаром» позначає його невідкладність. Тепер же, хоч Господь іноді й виявляє Свій гнів над грішниками, та відразу пом’якшує його й довго терпить, даючи місце їхньому покаянню."],"h":"Коли спалахне незабаром гнів Його"},{"v":"12","t":["Блаженні ті, хто нехтує земними благами, а всю свою надію, усе уповання покладає на Господа. Деякі стверджують, що цей псалом є продовженням попереднього, так що обидва вони разом становлять один псалом, і на цій підставі наприкінці роблять зауваження, що підходить до обох псалмів як до одного: блаженний Давид як почав блаженством, так і закінчив блаженством."],"h":"Блаженні всі, хто надіється на Нього"}],"3":[{"v":"1","t":["Надписання цього псалма ясне, особливо для людей, знайомих із книгами Царств (2Цар. 12:14). Він пасує не лише одному Давидові, а й кожному, хто зазнає нападів від ворогів видимих чи невидимих."],"h":"Псалом Давида, коли він утікав від Авессалома, сина свого"},{"v":"2","t":["Тяжко скорботячи, що зазнав такого зловмисного задуму від своїх домашніх і друзів, і спрямовуючи думки до єдиного Бога, пророк питає: чому з кожним днем дедалі більшає число його ворогів (саме їх назвав він «тими, що гноблять»), які цілими юрбами пристають до батьковбивці Авессалома, — яка тому причина, коли сам він (тобто пророк) не завдав жодному з них жодної кривди? Цими словами натякається також і на зловмисні задуми демонів проти нас."],"h":"Господи, чого намножилося тих, що гноблять мене?"},{"v":"2","t":["Це сказано для пояснення вислову «намножилося»."],"h":"Багато хто повстає на мене"},{"v":"3","t":["Багато хто, каже, з тих, що збурилися проти мене, підбадьорюючи один одного, розголошують про мою душу, тобто про мене самого, таке: якщо мене так легко можна було обернути на втечу, то це означає, що я покинутий Богом за свої гріхи. Або: так кажуть багато хто з тих, хто бачить ці мої лиха. «В Бозі його» — інакше кажучи: у тому Бозі, на Якого він (пророк) завжди надіявся."],"h":"Багато хто каже душі моїй: нема спасіння йому в Бозі його"},{"v":"4","t":["Нехай, каже, розголошують вони про мене, що хочуть; але Ти все-таки залишаєшся заступником усіх, хто перебуває в спокусах, а надто тих із них, хто виявляється гідним Твого заступництва."],"h":"Ти ж, Господи, Заступник мій"},{"v":"4","t":["Одні вбачають для себе славу (наприклад) у знатному походженні, або в щасті, або в багатстві, або, нарешті, ще в чомусь подібному; а я на Тебе єдиного уповаю і Тобою єдиним підношуся. Бо Ти прославиш мене, будучи моїм помічником, і піднесеш угору мою голову, колись переможну, а тепер схилену під тягарем лих."],"h":"Слава моя, і Ти підносиш голову мою"},{"v":"5","t":["Щойно, каже, я воззвав чуттєво (тобто устами) чи подумки, — Бог одразу ж і почув мене; бо Господь близький до всіх, хто прикликає Його. Горою святою пророк називає Сіон, де, як вірували, перебуває Бог і де Він розмовляє з людьми, гідними цього. Але під святою горою можна також розуміти небо, яке і ми називаємо оселею Божою."],"h":"Голосом моїм до Господа я воззвав, і Він почув мене з гори святої Своєї"},{"v":"6","t":["Уражений страшним тягарем скорбот, я, каже, зовсім занепав духом і нічого не робив (подібно до сплячого)."],"h":"Я заснув"},{"v":"6","t":["Довго, каже, перебував у такому стані."],"h":"І спав"},{"v":"6","t":["Але, передбачивши як пророк, що Ти допоможеш мені, я відразу ж, каже, підбадьорив свій занепалий дух. Деякі тлумачі стверджують, що це («заснув, спав, устав») сказано пророком про його воскресіння, замість ужити вислови: я засну, будучи мертвим, і спатиму довго, причому тіло моє лишатиметься бездіяльним; та по закінченні певного часу я пробуджуся — тобто тоді, коли Христос, зійшовши до аду, воскресить тих, хто там утримується, або ж коли Він воскресить усіх померлих наприкінці часів."],"h":"Устав, бо Господь заступиться за мене"},{"v":"7","t":["«Не побоюся», — каже, — саме уповаючи на Твоє заступництво. «Тими, що нападають», пророк називає тих, хто нападає на нього самого, тобто спільників Авессалома (історичний зміст), або ж демонів (переносний зміст). Щодо демонів, то напад їхній «довкола» так і слід розуміти: бо вони нападають і спереду, коли намагаються вселити в нас надію на щасливий успіх (наших починань), і ззаду, коли нагадуванням про наші колишні провини намагаються осквернити нашу душу; нападають далі праворуч, коли, сприяючи нам у добрих ділах, водночас збуджують у нас марнославство; нападають ліворуч, коли явно намагаються схилити нас до гріха."],"h":"Не побоюся тем людей, що довкола нападають на мене"},{"v":"8","t":["Представляючи довготерпіння Боже ніби певним сном, пророк каже «воскресни» замість того, щоб сказати: підвигнися на ворогів. А може, пророк провіщає в цьому місці воскресіння Спасителя з мертвих, прикликаючи Його до спасіння людей, яких пророк зображує тут у своїй особі («спаси мене»)."],"h":"Воскресни, Господи, спаси мене, Боже мій"},{"v":"8","t":["Наперед бачачи пророчими очима загибель своїх ворогів, пророк уже віддає подяку Богові й визнає подаровану Ним милість."],"h":"Бо Ти вразив усіх, хто ворогує зі мною марно"},{"v":"8","t":["Під «зубами», очевидно, розуміється сила; цей вислів метафорично взято від звірів, у яких сила зосереджена саме в зубах. «Грішниками» ж пророк називає всіх своїх ворогів, які, очевидно, грішили, бо вели війну проти нього марно, з самої лише злоби."],"h":"Зуби грішників Ти сокрушив"},{"v":"9","t":["Це також вигук подяки, що означає: спас його Господь, а не хтось інший."],"h":"Господнє — спасіння"},{"v":"9","t":["І зійшло, каже, благословення Твоє на народ Твій, або на тих, хто разом зі мною терпить напади від багатьох ворогів, — або ж узагалі на ціле моє царство, або, нарешті, на народ, що складається з віруючих у Христа. Під «благословенням» слід розуміти мир і благодіяння Божі як наслідок благословення Божого. Тому як сам цей народ прославив Бога, так і кожен інший, хто тільки бачив, яку допомогу дістав пророк від Господа."],"h":"І на людях Твоїх — благословення Твоє"}],"4":[{"v":"1","t":["Словами «на кінець» цей псалом надписано тому, що, як покажемо нижче, він містить серед іншого пророцтво про воскресіння з мертвих, яке, як нам відомо, належить майбутньому вікові й становить завершення віку теперішнього. «У піснях» же додано з тієї причини, що в ньому розповідається про дивні діла Господа, Який дарував пророкові перемогу над тираном Авессаломом, з якої нагоди й був оспіваний ним цей псалом."],"h":"Псалом Давида, на кінець, у піснях"},{"v":"2","t":["Дивіться, яка швидкість: він іще взиває, а вже почутий. Бо, як каже в іншому місці, «ти ще говоритимеш, а Він скаже: ось Я» (Іс. 58:9). Отже, не багатослів’я схиляє до нас Господа, а чисте розположення душі того, хто молиться. Вислів «Бог правди моєї» — це перифраз, ужитий замість слів «Бог мене, праведного», — мене, хто тільки через несправедливість Авессалома терпить кривди, бо сам я його не скривдив. Подібно пророк нерідко висловлюється про себе, називаючи себе праведним, а також святим і подібними іменами, звісно, не з бажання похвалитися собою, а порівнюючи себе з нечестям своїх противників."],"h":"Коли я взиваю, почув мене Бог правди моєї"},{"v":"2","t":["Радість ніби розширює душу (тобто робить її м’якшою, ніжнішою), а скорбота стискає її (тобто здавлює, перешкоджає виявленню цієї м’якості). Зі мною ж, каже пророк, сталося навпаки: коли спіткала мене скорбота, Ти, Боже, зробив мене набагато великодушнішим, так що я навіть наказав пощадити самого сина-батьковбивцю."],"h":"У скорботі Ти дав мені простір"},{"v":"2","t":["Пророк іще більше благає Бога бути до нього милосердним, і якби сталося йому знову зазнати спокус, хай не знехтує Господь молитви, яку він тоді підноситиме."],"h":"Змилуйся наді мною і вислухай молитву мою"},{"v":"3","t":["Тепер пророк спрямовує свою мову проти друзів і знайомих, які серед лих, що його здолали, намагалися допомагати йому теперішніми, тобто тимчасовими засобами. Тому він і каже, звертаючись до них: чому, коли спіткають вас скорботи, ви не підносите сердець ваших до Бога, а тягнете їх донизу (до землі), обтяжуючи людськими помислами й життєвими турботами? Вислів «сини людські» — знову перифраз, що становить особливість єврейської мови і вжитий замість «люди»."],"h":"Сини людські, доки будете тяжкосерді?"},{"v":"3","t":["Марні людські зусилля: спершу вони, мабуть, і тішать надією, але згодом виявляються даремними. Можливо також, що пророк звертається з цими словами не лише до своїх друзів і знайомих, а взагалі до тих людей, які прив’язані до теперішнього, як до чогось постійного й ніби не підвладного жодним змінам; а воно тим часом тільки здається сущим, і саме зі своєї зовнішньої, чуттям доступної сторони, насправді ж, через безперервні зміни, є чимсь несущим. Так і сам пророк, будучи царем, вів, однак, життя приватної людини й зазнавав переслідувань."],"h":"Навіщо любите марноту і шукаєте неправди?"},{"v":"4","t":["Сполучник «і», поставлений на початку вірша, зайвий; це не що інше, як особливість єврейського письма, яку ми нерідко можемо зустріти, а краще сказати — зустрінемо, якщо стежитимемо за цим. Отже, пізнайте, каже пророк, яким славним, дивним зробив мене Господь, — мене, хто був присвячений Йому й відданий цілковито, і в Ньому одному покладав свою надію. Та й як справді не славний був пророк, коли знищив того, хто задумав було знищити його самого, і коли, обернений спершу на втечу, з мізерними військовими силами здобув потім перемогу над своїм переслідувачем, що мав при собі численні війська?!"],"h":"І знайте, що Господь учинив дивним преподобного Свого"},{"v":"4","t":["Діставши такої швидкої допомоги цього разу й будучи врятований понад усяке сподівання від такої серйозної небезпеки, я пізнав, каже пророк, що Господь милостивий до мене, і я цілком певен, що Він почує мене й знову, коли я, застигнутий новими лихами, взиватиму до Нього про допомогу."],"h":"Господь почує мене, коли я воззву до Нього"},{"v":"5","t":["Гніватися, як людям, пророк не забороняє, але переконує нас, щоб ми, гніваючись, не згрішили; а це буває тоді, коли ми, захоплені запалом пристрасті, стаємо надмірно дратівливими й недоречно чи без жодної провини мстимося комусь, тим часом як гнів насаджено в людях саме для протидії вадам. Так, коли хтось гнівається, мстячи за заподіяну йому кривду, то грішить, а коли гнівається, щоб виправити іншого, то не грішить, як, наприклад, батько гнівається на свого зіпсованого сина."],"h":"Гнівайтеся, та не грішіть"},{"v":"5","t":["Відходячи, каже пророк, з настанням ночі на ваше ложе, яке дасть вам слушну нагоду відпочити від денних турбот, запитуйте на дозвіллі самих себе про ваші денні помисли; і якщо протягом дня ви помислили про щось нечисто, то постарайтеся покаятися в тому під час вашого спочинку на вашому ложі. Так, каже, чинив я сам і мав за те успіх в усьому; пізнавши наперед власним досвідом, як це корисно, я переконую тепер і вас чинити так само. А якщо, за словом пророка, слід віддаляти від себе навіть нечисті помисли, то тим більше треба віддаляти від себе самі нечисті дії. Зауважте ж тепер, як пророк користувався не лише засобами очисними, коли зазнавав спокус, а й запобіжними проти спокус. Так, «гнівайтеся, та не грішіть» — засіб запобіжний, а «що кажете в серцях ваших, на ложах ваших розчуліться» — очисний."],"h":"Що кажете в серцях ваших, на ложах ваших розчуліться"},{"v":"6","t":["Лише плоди вашої праведності, каже, принесіть у жертву Богові, нікого самі не кривдячи; і очікуйте собі допомоги від Господа, Який особливо благоволить являти Своє заступництво тим, хто терпить кривди. Пророк накреслює тут також і образ майбутньої Церкви Христової, де Богові мають приноситися жертви не речові, а духовні, що полягають, замість тварин, у добрих ділах. Під «правдою» ж («принесіть жертву правди») слід розуміти не правду у власному значенні, а взагалі всяку чесноту."],"h":"Принесіть жертву правди і уповайте на Господа"},{"v":"7","t":["Навівши вище (в. 5), як ми бачили, настанову з власного прикладу, пророк подає тут певне заперечення, яке могли б висунути проти нього малодушні люди. Інші, каже він, коли зазнають випробувань, впадаючи в зневіру, доходять до відчаю й не вірять, що Господь близький до тих, хто прикликає Його: у них вириваються вигуки на кшталт такого: «Хто буде нашим помічником?» На що вони ніби самі собі відповідають: «Ніхто». Це ознака крайнього ступеня відчаю. А може, тут ідеться також і про плотоугодників, які, вбачаючи все своє благо в неробстві й плотських утіхах, лише цього одного й прагнуть у житті і дуже не люблять нещасть, що посилаються на нас Божественним Промислом. У такому разі слова «хто покаже нам добре?» слід розуміти як вияв найпристраснішого прагнення душі до плотських насолод."],"h":"Багато хто каже: хто покаже нам добре?"},{"v":"7","t":["Інші, коли спіткають їх лиха, впадають у відчай; що ж до мене, то я, каже пророк, так не чиню, бо на мені явлено знамення Твого Божественного відвідання, під яким слід розуміти саме світло віри, як засіб, що розганяє темряву відчаю; це знамення, ніби накреслене на мені, зробило мене відомим не лише серед близьких, а й серед далеких. Деякі тлумачі гадають, що в наведеному місці міститься пророцтво про християн, на яких знаменовано, тобто покладено, особливу печать — Христа, тому вони й названі християнами, — Христа, Який є світлом Бога Отця (Ін. 14:9; Євр. 1:8). Самого ж себе, на їхню думку, пророк ставить нарівні з християнами через близьку спорідненість із ними в чесноті."],"h":"Знаменувалося на нас світло лиця Твого, Господи"},{"v":"8","t":["Тобто або через явлене Богом заступництво (якщо віднести до самого пророка), або ж через найменування віруючих іменем Христовим (якщо віднести до християн)."],"h":"Дав Ти веселість у серці моєму"},{"v":"8","t":["Мова знову про плотоугодників: що вони, як каже пророк, діставши все в достатку від безмірного божественного людинолюбства, все-таки думають про земне. Пророк перелічує й самі дані їм блага: плід, каже, пшениці, і вина, і олії примножено їм, тобто вони наситилися переліченими благами, під якими, як найістотнішими, без сумніву, слід розуміти й інші види їжі."],"h":"Від плоду пшениці, вина й олії своєї вони намножилися"},{"v":"9","t":["Відклавши набік страх, що мучив мене, я засну, каже пророк, безтурботним сном, та й не лише засну, а й висплюся досхочу. Вислів «разом» означає те саме, що водночас; тобто я зроблю, каже він, і те, і те одночасно: і засну, і спочину. Висловом «спочину» пророк позначає глибокий і тривалий сон. Можна розуміти це місце ще й так, що пророк говорить тут не про звичайний сон, а провіщає власну кончину — що помер він не насильницькою, а природною смертю. «Разом» же в такому разі слід розуміти як сказане про тіло й душу, тобто засну я, ніби каже пророк, у мирі водночас і тілом, і душею: (засну в мирі) тілом, бо йому більше не загрожують видимі вороги; (засну в мирі) душею, бо вона в безпеці від ворогів невидимих. Тоді «спочину» матиме такий зміст: спочину, інакше — засну на довгий час, до дня воскресіння."],"h":"У мирі разом засну і спочину"},{"v":"9","t":["Ти оселив, каже, мене окремо від людей нечестивих, у надії спасіння. Деякі тлумачі стверджують, що пророк провіщає тут про воскресіння з мертвих, представляючи ніби саме тіло таким, що звертається з цими словами до Бога. «Господи, — ніби так каже воно, — Ти розлучив мене з моєю спільницею — душею, оселивши в гробі, розлучив, однак, не цілком, а в надії воскресіння, коли я знову прийму в себе цю душу». Слово «бо» видається тут ніби непотрібним. Як у цьому, так і в багатьох інших місцях воно становить лише одну з особливостей мови Святого Письма Старого Завіту, що не має в мові жодного логічного значення. Утім, тут воно, мабуть, могло бути вжите й у значенні ствердження — замість «справді» чи «дійсно»."],"h":"Бо Ти, Господи, окремо в уповані оселив мене"}],"5":[{"v":"1","t":["Про те, що означає надписання «на кінець», почасти говорилося вище (Пс. 4). Деякі тлумачі гадають, що в цьому випадку надпис указує на той час, коли Ісус Христос благоволив стати людиною; бо тоді прийшла до кінця, або минула, тінь давнього закону. Цю свою думку вони обґрунтовують тим, що пророк пише цей псалом від імені майбутньої Церкви віруючих у Христа, хоча він анітрохи не менше пасує й до обставин життя самого пророка. «Тією, що успадковує», він назвав тут Церкву як усиновлену Богові через відродження (нове буття) хрещення. А спадщина її така, що її й «око не бачило» (1Кор. 2:9) тощо. Апостол Павло говорить про неї також як про наречену Христову: «Я заручив вас, щоб чистою дівою поставити перед Христом» (2Кор. 11:2). Так само й євангелист Іоан: «Хто має наречену, той наречений» (Ін. 3:29). Та й сам пророк Давид в одному місці говорить про неї так: «Стала цариця праворуч Тебе» (Пс. 44:10). Нарешті, щодо того, чому пророк назвав Церкву «тією, що успадковує», а не тією, що успадкувала чи успадкує, — то це тому, що ця її спадщина вічна й ніколи не припиняється."],"h":"На кінець, про ту, що успадковує"},{"v":"2","t":["Пророк лише різними й подібними за значенням висловами повторює тут те саме моління, як це звичайно буває, коли просять про щось від серця. Або ж «словами» він називає тут молитву як виражену словами; вислів «зойк» додає, щоб показати, що тоді, як звертається він із цією молитвою до Бога, його дух перебуває в сильному напруженні; а слово «голос» додано, щоб позначити, що напружена молитва пророка виливається у висловах ясних і зрозумілих, тоді як зойк загалом — це неясний і безладний крик людини. Далі інші слова взятого тексту, пов’язані з цими, зберігають своє самостійне значення. Так, «вислухай» означає не просто «почуй», а «зрозумій» або «завваж», про що я прошу в моїй молитві, і не вважай її малозначною, ніби вона вимовляється лише устами й звуком голосу (без ясного усвідомлення потреби того, про що молиться). Це людиноподібне зображення божественних дій, що становить одну з особливостей Святого Письма; це ми побачимо й далі."],"h":"Слова мої вислухай, Господи, зрозумій зойк мій, почуй голос моління мого"},{"v":"2","t":["Адже Ти, каже, тільки один і є в мене Цар, що піклується про мене, Ти тільки один і Бог у мене, Творець усього; ідолів же я відкинув (або відкинула, якщо припустити, що тут говорить Церква, — див. нижче)."],"h":"Царю мій і Боже мій"},{"v":"3-4","t":["Почуй, каже, мене, Господи, бо віднині я тільки до Тебе одного звертатимусь з молитвою, а не до іншого бога, як це було досі."],"h":"Бо до Тебе помолюся, Господи"},{"v":"3-4","t":["Того ранку, кажу я (тобто Церква), коли зійде для людства Сонце правди — Христос, почуй мене; бо тоді я складуся з язичників і юдеїв і прикликатиму Тебе на допомогу. Мало того: через близькість до Тебе, завдяки моєму доброчесному життю, я стану перед Тобою, і Ти так завважиш мене, ще коли я наближатимусь до Тебе. Бо, як сказано, «очі Господні — на праведних» (Пс. 33:16). У деяких списках псалмів трапляється не «побачиш», а «побачена буду», інакше кажучи: стану видимою. Щодо ж самого Давида (якби ми стали пояснювати це місце історично), то «вранці», звісно, слід розуміти як ранковий час. Бо він ніби так каже: перш ніж рано-вранці візьмуся за якусь справу, я прикликатиму Тебе на допомогу, Боже, і так далі, — що робимо й ми самі, щойно встанемо з нічного нашого ложа. Утім, я аж ніяк не хочу цим сказати, ніби в інший час (крім самого ранку) молитися не слід. «Благословлятиму, — каже пророк, — Господа повсякчас» (Пс. 33:2)."],"h":"Уранці почуй голос мій, уранці стану перед Тобою, і побачиш мене"},{"v":"3-4","t":["Бо беззаконня люблять ідоли. Під «беззаконням» тут розуміється взагалі всякий гріх."],"h":"Бо Ти — Бог, що не хоче беззаконня"},{"v":"6","t":["Язичницькі боги не лише самі сповнені пристрастей, як ми дізнаємося про це з творів язичницьких письменників, а й особливо прихильні (за оповідями їхніх книг), як до своїх близьких, навіть до тих людей, які ревнують у їхніх порочних пристрастях, і відкривають для них свої нечисті святилища. Не такий Ти, каже, Господи: Твоєї близькості й Твого покровительства (саме так слід розуміти в цьому випадку вислів «не оселиться») ніколи вже не сподобиться людина лукава. Бо, як сказано, «близько Господь до скрушених серцем» (Пс. 33:19); і далі: «близько до тих, хто боїться Його» (Пс. 84:10). Під людиною «лукавою» тут розуміється грішник у всьому."],"h":"Не оселиться біля Тебе лукавий"},{"v":"6","t":["У цих словах, як гадають, міститься пророцтво про юдеїв, які, доки залишалися вірними законові Божому, звичайно сподоблялися божественного покровительства, а щойно ставали його порушниками, одразу ж справедливо були відкинуті Богом."],"h":"Ані перебуватимуть беззаконники перед очима Твоїми"},{"v":"7","t":["А це сказано про язичників, що не вірують в істинного Бога й не прийняли закону Божого. Тут треба відрізняти законопорушника від беззаконника: законопорушник — той, хто знає закон, але переступає його; беззаконник же — той, хто зовсім не дістав жодного закону. Але ми нерідко, змішуючи ці два поняття, і законопорушника називаємо беззаконником, як такого, що не дотримується закону. Сказавши загалом про грішників, пророк перелічує далі окремо й ті гріхи, що здавалися йому свого часу істотнішими й головнішими."],"h":"Ти зненавидів усіх, хто чинить беззаконня"},{"v":"7","t":["У щойно наведених словах ідеться головно про тих, хто шанує не Бога істинного, а інших богів, — і далі про єретиків, а за ними й про всіх узагалі людей, як з юдеїв, так і з язичників, які в будь-який спосіб впадають у неправду; бо й вони — служителі не Бога істинного, а диявола, бо сатана — батько неправди. Висловом же «погубиш» пророк хотів зобразити найтяжче покарання цих людей. А може, пророк ужив цей вислів також і для того, щоб тим легше налякати людей, схильних до неправди, легковажних і безтурботних, які так завдають шкоди не лише собі самим, а й стають причиною загибелі для багатьох інших."],"h":"Погубиш усіх, хто говорить неправду"},{"v":"8","t":["Завважте, як пророк до вбивства долучає також і підступ; бо і той, хто лестить підступно, і той, хто наражає на небезпеку життя ближнього, за суттю справи однаково є вбивцями."],"h":"Чоловіка кровожерного й підступного гидує Господь"},{"v":"8","t":["Я, каже Церква про себе, з великої Твоєї милості, звільнившись від омани, ввійду тепер у Твій, Господи, дім, який я колись нерозумно намагалася руйнувати. Або інакше: «ввійду в дім Твій», сподобившись такої близькості до Тебе не за свої власні чесноти, а тільки з однієї Твоєї милості. «Дім же Божий», на думку деяких тлумачів, є не що інше, як доброчесне життя; бо справді Господь спочиває й перебуває в тих, хто намагається вести доброчесне життя, як сказав Сам Спаситель у Євангелії, що Він і Отець Його прийдуть і оселю в такої людини створять (Ін. 14:23)."],"h":"А я з великої милості Твоєї ввійду в дім Твій"},{"v":"8","t":["Тим часом як язичники, не боячись справедливої кари, дозволяють собі безрозсудно поводитися в храмах своїх богів, я, каже Церква, з усяким благоговінням і в страху впаду ниць перед Тобою — і в Твоєму храмі земному, і в храмі небесному. У застосуванні до самого пророка наведені вище слова матимуть той зміст, що пророк, оглянувши головні види злочинів і показавши всю їхню мерзоту, звертається далі до себе самого й дає обітницю перед Богом служити Йому щиро й ревно, і не як виправданий, а як помилуваний; хоча в сказаних словах пророк докоряє язичникам, а себе вводить у храм Божий, і тому, здавалося б, це мало б означати щось інше."],"h":"Поклонюся до храму святого Твого в страху Твоєму"},{"v":"9","t":["Провадь, каже, мене через Твого Сина, Який, за апостолом, є праведністю, і освяченням, і викупленням нашим (1Кор. 1:30), — і в Твоєму законі, що становить людську праведність."],"h":"Господи, настав мене правдою Твоєю"},{"v":"9","t":["Вороги мої, каже, видимі й невидимі, всюди розставляють на стежці моїй перешкоди й спокуси; тому, благаю Тебе, Боже, вирівняй (саме так перекладає Сіммах вислів «випрям») мою путь до Тебе. Або ж: «випрям» (тобто мене) так, щоб мені не ухилятися ні праворуч, ні ліворуч, аби уникнути таємних підступів моїх ворогів. Наведені вище слова псалма, хоч стосуються власне Церкви, пасують і самому Давидові."],"h":"Заради ворогів моїх випрям перед Тобою путь мій"},{"v":"10","t":["Вони (тобто вороги) безперестанку говорять неправду, бо вони обманщики, — і завжди зайняті думками непотрібними й порожніми, бо разом із тим і люди підступні."],"h":"Бо нема в устах їхніх істини, серце їхнє марне"},{"v":"10","t":["Це сказано або через мертві догмати й смердюче богохульство єретиків, або ж через їхні безрозсудні вислови, що взагалі швидко розкладаються, подібно до мертвого трупа, або, нарешті (скажемо на підставі історії), через мерзенну пиху, якою сповнені були промови Давидових ворогів. А могила, якщо тільки вона закрита, приховує не лише труп, що в ній, а й поганий запах, який він видає."],"h":"Відкрита могила — гортань їхня"},{"v":"10","t":["Кожен підступний водночас і брехун, але не кожен брехун буває людиною підступною, і злі дії підступної людини значно небезпечніші й шкідливіші. А проти мене, каже, мої вороги діяли водночас і неправдою, і підступом."],"h":"Язиками своїми лестили підступно"},{"v":"11","t":["Ти, каже, Боже, — Ти, Якому ненависні всі, хто чинить подібним чином, як Ти вже сказав (Пс. 5:5–7), Сам розсуди їх."],"h":"Суди їх, Боже"},{"v":"11","t":["Інакше кажучи: хай вони обдуряться у своїх розрахунках."],"h":"Хай відпадуть від задумів своїх"},{"v":"11","t":["За їхнє нечестя, каже, «вижени» (тобто прожени від Себе, відкинь) їх, бо вони Тебе не шанують; і я не заради себе прошу тут Тебе про це, хоч і я — спадщина Твоя, Боже. Або інакше: що більше сповнюються вони нечестя, то швидше віддаляють себе від Твого благовоління. Нечестивим же вважається не лише той, хто не шанує Бога, а й той, хто шанує Його не так, як личить істинному Богові."],"h":"За множеством нечестя їхнього вижени їх"},{"v":"11","t":["Не так, каже, тривожить мене те, що вони замишляють проти мене, як скорблю я про те, що вони чинять проти Тебе, Боже: вони прогнівили Тебе своїми злими намірами, про які ми згадували вище. Або інакше: вони гнівлять Тебе, мого Господа, ворогуючи проти мене, хто зберігає Твої повеління."],"h":"Бо вони прогнівили Тебе, Господи"},{"v":"12","t":["Так, коли вороги Твої відкинуті Тобою, праведники, навпаки, сповнюються радості, бо вони, уповаючи на Тебе одного, беруть гору над стількома й такими ворогами."],"h":"І хай звеселяться всі, хто уповає на Тебе"},{"v":"12","t":["Інакше кажучи: вічно й безперестанку, щоразу дістаючи швидку Твою втіху."],"h":"Повіки радітимуть"},{"v":"12","t":["Заспокоювані, звісно, красою своїх душ, вони «повіки радітимуть». Бо, каже Писання, «оселюся в них, і ходитиму, і буду їм Богом, а вони будуть Мені народом» (Лев. 26:12; 1Кор. 6:16)."],"h":"І Ти оселишся в них"},{"v":"12","t":["Бо тільки вони одні пізнали Бога істинного і на Ньому одному утвердили свої уповання. Або інакше: християни так люблять божественне ім’я Христове, що з нього одного хочуть бути впізнаваними і самим лише Христом хваляться, за апостолом: «А я, — каже, — хай не хвалюся нічим, хіба тільки хрестом Господа нашого Ісуса Христа» (Гал. 6:14), тобто тільки Самим Христом розіп’ятим."],"h":"І хвалитимуться Тобою ті, хто любить ім’я Твоє"},{"v":"13","t":["Прославляючи його не лише в цьому житті, а й у майбутньому, коли Ти скажеш: «Прийдіть, благословенні Отця Мого» (Мф. 25:34). Отже, Ти, каже, благословиш його, а нечестиві його ганять. Цими словами він утішає тих, хто терпить хулу за своє доброчесне життя."],"h":"Бо Ти благословиш праведника, Господи"},{"v":"13","t":["Ти, каже, Господи, міцно огородив і надійно захистив нас хрестом Твоїм — цим щитом благовоління, тобто Твого невимовного задуму. Або далі: під «зброєю благовоління» слід розуміти надійний і міцний щит. Цей вислів властивий Святому Письму Старого Завіту; так кажуть: «син сили» замість «сильний», і «муж кровей» замість «спраглий убивства чи крові», і «людина миру» замість «сумирна». Так слід розуміти й це, відповідно до інших висловів: Ти захистив нас Своєю міццю, як щитом славним і міцним. Бо вінець — це саме коло, що огортає й захищає."],"h":"Як зброєю благовоління, увінчав Ти нас"}],"6":[{"v":"1","t":["Що означає надписання «на кінець», про те вже говорилося раніше (Пс. 4 і Пс. 5). «У піснях» же надписано цей псалом тому, що в ньому містяться «пісні» й величання, складені пророком на славу Божу, — а далі його моління «про восьмий», тобто про майбутній вік. Сьомий — це вік теперішній, бо він вимірюється седмицями, складається з седмиць і в седмицях повторюється; а майбутній вік називається восьмим, як той, що настає за теперішнім — сьомим. Свою молитву щодо майбутнього віку пророк підносить тут до Господа не лише від власного імені, а й від імені всіх нас, як до майбутнього нашого спільного Судді. Написано цей псалом після того, як пророк зазнав тих тяжких випробувань, що були послані на нього Богом за деякі його гріхи."],"h":"На кінець, у піснях, про восьмий, псалом Давида"},{"v":"2","t":["У книзі ж Йова, навпаки, говориться: «Блаженна людина, яку викриває Бог» (Йов. 5:17). Та й сам Давид в одному місці міркує про це, здавалося б, інакше, а саме каже так: «Блаженна людина, яку Ти караєш, Господи» (Пс. 93:12). Але й у наведених вище словах пророк зовсім не хоче відвернути від себе викриття й покарання Боже; він лише просить у Господа, щоб це Його викриття й покарання не було поєднане з роздратуванням («люттю») і гнівом, бо пророк знав, що гнів Божий нестерпний, і боявся, щоб йому не загинути від нього цілковито; тому й просить Бога, щоб відвідання Господнє було спокійним, від якого той, кого відвідують, міг би виправитися і тим легше уникнути страшного покарання за свої гріхи на майбутньому суді Божому. Ось чому і в своїй молитві він поставив спершу викриття, а потім покарання, як те, що йде за першим. Утім, зауважимо, що все Боже вільне від дратівливості й будь-якої пристрасті. І якщо пророки приписують Богові подібні душевні стани, то тільки тому, а краще сказати — для того, щоб показати нам, людям, що Господь піклується про кожного з нас; що Він усе бачить і чує; що Він радіє й сумує, осуджує, дратується, гнівається тощо; — кажуть це далі для того, щоб ми, так налякані, утрималися від своїх вад. Або інакше: якщо пророки намагаються пояснювати людськими діями дії божественні, то це лише означає, що як ті, хто говорить, тобто самі пророки, так і ті, хто їх слухає, — люди, і тому те, що перші хочуть повідомити другим про Бога, висловлюють перед ними й людською мовою. Та й не може бути інакше, щоб сущі в тілі розмовляли між собою якось інакше, а не тілесно ж. Так само (наприклад), звертаючись зі своєю мовою до чужинців, ми намагаємося вживати при цьому їхню рідну мову, щоб бути їм зрозумілими. Або, розмовляючи (наприклад) з дітьми, ми намагаємося наслідувати їхню вимову, і шепелявимо, і пристосовуємося до їхніх дитячих понять, хоч би самі були в сто разів розумніші за них. Приймімо це за загальне правило для всіх подібних випадків, що можуть трапитися під час читання псалмів. Отже, слова пророка «не в люті Твоїй карай мене, ані в гніві Твоєму» можна висловити так: не осуди мене, Господи, як ніби каже він, за заслугами й не піддай мене заслуженому мною покаранню."],"h":"Господи, не в люті Твоїй викривай мене, ані в гніві Твоєму карай мене"},{"v":"3","t":["Якби, каже, мій розум не був «немічним», то страждання не змогли б його зламати. Або ж пророк хоче висловити цим ту думку, що він виявляється «немічним» для боротьби зі своїм невидимим ворогом, який явно й таємно підступно діє проти нього. Або також: що він ніби став «немічним», знесилений пристрастями. Отже, пророк ніби так каже, звертаючись до Бога: зваж, Боже, на мою неміч і не осуди мене остаточно; адже я не з доброї волі піддаюся моєму ворогові. У такому взиванні до Господа, яким взивав пророк, тобто «помилуй мене», — усі ми маємо потребу щогодини. Бо в одному місці той самий пророк каже: «Якщо Ти, Господи, зважатимеш на беззаконня, Господи, хто встоїть?» (Пс. 129:3). І ще: «Бо не виправдається перед Тобою жоден живий» (Пс. 142:2). Так само й інший пророк каже: «Хто похвалиться, що має серце чисте, або хто скаже, що чистий від скверни?» Так, усі ми маємо потребу в Божому милосерді, але не всі його дістаємо; бо милосердя Боже шукає лише людини, гідної цього. І «немічні» також усі ми; бо «якщо не Господь збудує дім, марно трудяться будівничі» (Пс. 126:1). І: «якщо не Господь зберігатиме місто, марно не спить сторож» (Пс. 126:1)."],"h":"Помилуй мене, Господи, бо я немічний"},{"v":"3","t":["Скорбота від випробувань у мені, каже, така сильна, що доходить до моїх костей, і навіть їх потрясла, хоч вони позбавлені чутливості. Цим пророк хотів зобразити найкрайніший ступінь, якого досягла душевна скорбота, що він її зазнавав. Або також: під костями можна розуміти сили й здібності розуму, якими він опирається випробуванням."],"h":"Зціли мене, Господи, бо збентежилися кості мої"},{"v":"4","t":["Тобто не витримавши сили скорбот. Цей вислів особливо пасує до тих випадків, коли хтось буває збуджений до якогось безрозсудного гніву чи ганебної пристрасті. Бо тоді диявол, з силою кидаючись на нас, подібно до сильного вітру, що хвилює море, намагається збурити і тіло наше, і нашу душу, і тоді як тіло, так і душа наша приходять у розлад, бурхають і не зберігають свого власного призначення й ладу."],"h":"І душа моя збентежилася дуже"},{"v":"4","t":["Це голос не людини, що ремствує на Бога, а людини, змученої скорботами. Я, каже пророк, довго залишався ніби в якомусь забутті в Тебе, Господи; а тим часом я був у такому стані, що дуже потребував Твоєї допомоги. Бо до тих, хто зазнає спокус від власних гріхів, Господь не одразу поспішає на допомогу, з великого Свого промислу. «Під час благоприємний, — каже, — Я почув тебе». Натомість до тих, хто зазнає спокус через підступи лукавого, Господь швидко поспішає зі Своєю всесильною допомогою. «Ти ще говоритимеш, — сказано в Писанні, — а Я скажу: ось Я»."],"h":"І Ти, Господи, доки?"},{"v":"5","t":["Хоч Ти, Господи, і відвернув лице Твоє від мене за мої гріхи, але поверни, каже, його знову до мене і визволи мене від скорбот моїх."],"h":"Повернися до мене, Господи, визволи душу мою"},{"v":"5","t":["Прошу, каже, я цього не за власні добрі діла, бо їх у мене немає, а з милості Твоєї."],"h":"Спаси мене заради милості Твоєї"},{"v":"6","t":["Смертю тут пророк називає гріх, бо він — винуватець смерті; адже спершу з’явився у світі гріх, а за ним уже з’явилася й смерть як його наслідок. Отже, каже пророк, той, хто чинить гріх, у ту саму мить уже не пам’ятає про Бога, ніби сп’янілий від цього гріха й засліплений ним. Або ж пророк називає тут «смертю» час кончини, коли людина разом із життям утрачає й можливість пам’ятати про Бога чи прикликати Його собі на допомогу, бо тоді це прикликання вже марне."],"h":"Бо в смерті нема того, хто згадує Тебе"},{"v":"6","t":["Каяття в учинених гріхах звичайно буває лише перед смертю; а потім — за нею настає вже власне час відплати."],"h":"А в аді хто визнає Тебе?"},{"v":"7","t":["Не просто, каже, я трудився, а трудився, видаючи стогони; а це свідчить про дуже посилений труд. І не сказав так само просто: «поплачу» чи «проллю сльози», а сказав: «скупаю в сльозах моє ложе», — і до того ж не раз і не двічі, а так, каже, чинитиму щоночі. Удень відволікають мене від цього різні турботи, тому час відпочинку від денних турбот (тобто ніч) я й зроблю для себе часом сповіді, коли ніхто й ніщо мене не турбує. І справді, нічний час — найзручніший для покаяння. Далі слова «сльозами моїми постіль мою зрошуватиму» становлять додаток до попередніх слів «омиватиму кожної ночі ложе моє», доповнюючи й пояснюючи перші. Послухаймо ж тепер ми, прості смертні, як кається такий великий цар, яким був пророк, і наслідуймо його в цьому. Наведені вище слова пророк вимовляє з метою якнайшвидше й найлегше схилити на милість милосердного до нас Господа, щоб тривалий час лиха не надломив у пророкові сил його духу й не зробив його ні до чого доброго нездатним (щоб явив йому Господь Своє милосердя)."],"h":"Утомився я від зітхання мого, омиватиму кожної ночі ложе моє, сльозами моїми постіль мою зрошуватиму"},{"v":"8","t":["Звісно, збентежилося око душі пророка, тобто розум. Бо, знаючи праведний гнів Твій проти грішників у день суду, я, ніби так каже він, прийшов у сильне занепокоєння. Розум же пророк назвав оком якнайдоречніше, бо він справді служить людині провідником на всіх шляхах її життя. Так, розум наш і бачить, розум і чує. Деякі, втім, тлумачі гадають, що збентежилося в пророка його тілесне око, коли сам він розгнівався на своїх ворогів, бо це саме властиве, як кажуть вони, тим людям, яких хтось сильно розгнівав."],"h":"Збентежилося від гніву око моє"},{"v":"8","t":["Наче яку стару одежу, закинули й зневажають, каже, мене мої вороги; а тим часом вони боялися мене раніше, доки я не згрішив. Або: «постарів», інакше кажучи — став старим і слабшим, ніж був колись, замолоду; бо саме під старість люди слабшають силами."],"h":"Постарів я серед усіх ворогів моїх"},{"v":"9","t":["Знаючи, що Господь уже явить йому Свою допомогу, пророк підбадьорюється духом і, страхаючи своїх ворогів, видимих і невидимих, наказує їм тікати геть від нього."],"h":"Відступіть від мене всі, хто чинить беззаконня"},{"v":"10","t":["Саме в цьому пророк убачає причину власного підбадьорення, а також боязкості й утечі своїх ворогів. Або: усі наведені слова вжито тут у власному значенні, як це можна зустріти й в інших місцях. Або, нарешті: оскільки буває, що люди плачуть або від бідності, або від якихось інших нещасть, то пророк, додаючи до слів «голос плачу» слово «моління», хоче цим відрізнити від першого виду плачу свій плач, що прийшов на допомогу його молінню; а до цього останнього слова знову додає слово «молитва», яке свідчить про найвищий ступінь молитовного напруження в пророкові."],"h":"Бо почув Господь голос плачу мого, почув Господь моління моє, Господь молитву мою прийняв"},{"v":"11","t":["Пророк молить Бога, щоб швидше настало те, що має означати близький кінець його лих. І як не залишаться осоромленими тоді його вороги, коли побачать раптом, що марними виявляються всі їхні надії, ніби пророка, позбавленого Божого благовоління, тепер легко буде перемогти; а так осоромлені — як не злякаються його знову?"],"h":"Хай засоромляться й збентежаться всі вороги мої"},{"v":"11","t":["Опинившись у такому становищі, вони, каже, відступлять назад. Вислів «засоромляться» вказує на сильний сором. Далі слова «дуже скоро» становлять ніби загальний додаток до перших, у яких висловлюється лише одне бажання; а тут виражається молитва пророка про те, щоб це бажання його здійснилося якнайшвидше і його вороги зазнали того, на що заслуговують. Деякі, втім, тлумачі псалмів гадають, що в наведених вище словах пророка міститься радше молитва, а не якесь лихе побажання щодо його ворогів; а саме, кажуть вони, пророк молиться за своїх ворогів, щоб вони, радячись на зле, відчули спершу сором, потім страх від того, що Сам Бог — його помічник; щоб вони відстали від власного нечестя і так стали кращими."],"h":"Хай повернуться і засоромляться дуже скоро"}],"7":[{"v":"1","t":["Таке надписання цього псалма, здавалося б, зовсім не узгоджується з книгами Царств (2Цар. 17), де записано діяння Давида. Там також згадується ім’я Хусія, тільки там він вважається сином не Ємени, а Архі. Але цю суперечність неважко примирити, припустивши або те, що батько Хусія мав два імені, або що сам Хусій згодом прийняв назву сина Ємениного. Відомо, що саме цей Хусій, син Архі й союзник Давида, рухомий давньою дружбою до нього, удав, ніби зраджує царя, і пристав до Авессалома (коли той збурився проти свого батька), пристав із тим наміром, щоб зруйнувати задуми Ахітофела, найдосвідченішого провідника Авессалома, у чому й досяг успіху. Всупереч порадам Ахітофела, він постарався стримати й відвернути батьковбивцю від рішучих дій, а через це дав Давидові, що обернувся на втечу, змогу якнайдалі втекти від свого ворога й час зібратися з силами, як дуже докладно описується в книгах Царств. Ось за цей геройський учинок Хусієві й було присвоєно прізвисько сина Ємениного, бо «син Ємени» означає те саме, що «син правиці». А ми знаємо, що в Писанні діти називаються за їхніми батьками, а також людям присвоюються найменування за їхніми властивостями, як-от найменування «син миру», «чада мудрості» чи «син погибелі»; так само і цей муж названий «сином правиці», як людина праведна і найближча та найкорисніша для свого друга. Слід зауважити також, що в надписанні сказано «з приводу слів Хусія», а тим часом у всьому псалмі Давид жодного разу не згадує про Хусія; звідси народжується, здавалося б, нова трудність: як це надписання може в’язатися з самим псалмом? Не забуваймо при цьому того, що нам добре відомо, а саме, що пророк оспівав цей псалом Господу тоді, коли каявся, що понадіявся на хитрість Хусія, коли той запропонував йому свій план щодо обману Авессалома й руйнування Ахітофелової ради; оспівав, отже, не за той щасливий кінець війни, яким він завдячував хитрості Хусія, а каючись, що, відклавши надію на Бога, поклав своє уповання на слова, які мав сказати Хусій Авессаломові, і навіть сам послав його до того. Отже, цей псалом — пісня умилостивлення, якою пророк намагається схилити Бога до милості й у якій прикликає Його собі на допомогу."],"h":"Псалом Давида, який він оспівав Господу з приводу слів Хусія, сина Ємениного"},{"v":"2","t":["Якщо, каже, хитрість Хусія й принесла мені певну частку користі, давши змогу трохи підбадьоритися й виграти час, щоб зібратися з силами й приготуватися до відсічі, зате тепер, перед близькою битвою, я вже не покладаю більше на нього своїх надій; тепер я хочу цілком залежати від одного Тебе, Боже мій, і на Тебе одного передусім покладаю своє уповання, а все інше — друзів, союзників і воїнів — ставлю на другому місці. Бо написано: «Проклята людина, яка надіється на людину» (Єр. 17:5). Як не слід нічого шанувати нарівні з Богом, так само не слід і надіятися ні на кого іншого, крім Бога. «Спаси» — спасається той, кого оберігають від ран серед битви; «визволи» — визволяється той, кого всюди захищають від нападників; «від усіх, хто гонить» — це означає від тих, хто перекинувся до батьковбивці, разом із ним заплямувавши себе кров’ю і прагнучи смерті пророка. Або інакше: спасається той, хто хворий, визволяється ж той, хто в полоні. Отже, «спаси», каже пророк, мене, як недужого, і «визволи» мене, як бранця, бо я боюся, щоб знову не потрапити мені до рук моїх ворогів. Або ще: «спаси», каже, мене від ворогів видимих, які переслідують мене в цьому житті, і «визволи» від ворогів невидимих, які відразу після людської смерті ретельно шукатимуть плям гріха на моїй душі й усіляко намагатимуться заволодіти нею. Отже, тут міститься подвійне моління пророка: по-перше — моління за життя теперішнє, і по-друге — за життя майбутнє."],"h":"Господи, Боже мій, на Тебе уповаю, спаси мене від усіх, хто гонить мене, і визволи мене"},{"v":"3","t":["Левом пророк називає тут Авессалома за його нестримну зухвалість. А може, пророк розуміє тут також і диявола. Бо як лев має смердючу пащу, так смердючі вони й у диявола, що вивергає хулу. Під час Свого страждання Господь сказав: «Іде бо князь світу цього, а в Мені він не має нічого» (Ін. 14:30). Щодо Авессалома під душею, звісно, слід розуміти життя пророка, яке могло бути відняте в нього батьковбивцею. Бо душа — причина нашого життя; але ми нерідко самі наслідки називаємо іменами причин, від яких вони походять. Так, Бог — винуватець миру, правди тощо, і ми говоримо про Нього, що Він — правда, мир і так далі; натомість про диявола говоримо, що він — гріх і погибель, бо він справді є причиною, яка все це породжує. Далі слово «схопив» має тут не власне значення; воно вжите в значенні відняття чи позбавлення. Цей псалом пасує кожному, хто перебуває в спокусах; але в такому разі під гонителями слід розуміти демонів, а під левом — самого їхнього начальника, сатану, який намагається вловити наші душі в гріх і відчай або ж схопити їх тоді, як вони вийдуть зі своїх тіл, тобто після смерті."],"h":"Щоб не схопив (ворог), як лев, душі моєї"},{"v":"3","t":["Ці слова схожі з тими, що містяться у 2-му вірші, і мають однакове з ними значення. Так, тут «того, хто спасає» виражає те саме, що там «спаси» (Пс. 7:2), а «того, хто визволяє» — те саме, що «визволи». Якщо тільки Ти не благоволиш, ніби так каже пророк, явити мені Свою допомогу, то вже не знайдеться нікого, хто спас би чи визволив мене."],"h":"Коли нема того, хто визволяє, ані того, хто спасає"},{"v":"4-5","t":["Пророк не відкриває самого роду гріха, усе ще жаліючи свого сина, не називає й його на ім’я, соромлячись за його долю, а намагається висловлюватися радше натяками. Якщо, каже, я вчинив моєму синові те, що він дозволив собі вчинити мені, — а він був батьковбивцею й лиходієм; якщо, каже, я досі завдав йому якоїсь образи «руками», тобто діями, хоч сам я вже давно передчував його підступний задум; якщо, каже, нарешті, я заподіяв якусь шкоду тим, хто допомагав Авессаломові у війні проти мене, віддаючи мені тепер злом за отримані від мене благодіяння, — якщо все це я вчинив, то хай не здолаю я «ворогів» моїх. Але як же він каже, що не «віддає» їм злом, коли відомо, що він здобув перемогу над ворогами, причому загинув і сам Авессалом? На це можна відповісти, що тут ідеться про час, який передував заколотові. Пророк, нерідко зустрічаючи до того часу людей підступних, не відплачував їм за це; тільки тепер, перед загрозою своєму життю, він удався до самозахисту, не маючи сили довше терпіти таке зухвале беззаконня зловмисних людей. Можна також витлумачити слова пророка й так: хай упаду я, ніби так каже він, від ворогів моїх «порожнім», тобто ошуканим у своїх надіях. А ці надії пророка полягали саме в тому, що, може, він не буде змушений удатися до покарання своїх ворогів, а одним своїм появленням перед ними змусить їх розбігтися й припинити подальше переслідування його та полишити свої підступні задуми на його життя. Подивіться справді (2Цар. 18), з якою передбачливістю й дбайливістю він наказує воїнам пощадити його сина і потім, діставши звістку про його смерть, як гірко він за ним тужить! Або ще інакше: під ворогами в наведеному вище місці можна розуміти ворогів невидимих, упасти від яких порожнім і ні в чому не досягти успіху означатиме не здобути над ними гори й не встигнути осоромити їх твердинею своїх чеснот. Надаючи такого змісту словам пророка, слід, однак, зауважити, що говорить їх не марнославець, а людина, сама наражена на небезпеку, що він виставляє їх як знак, яким благають про допомогу. Ми можемо також відносити це місце й до деяких інших осіб, які мали стосунок до пророка; у такому разі слова пророка означатимуть ось що: я, ніби так каже він, тепер насильством вигнаний зі свого царства, нікого не скривдив, я не відплатив злом навіть Саулові (наприклад), який готував мені явну смерть, а тим часом він потрапляв і до моїх рук, як свідчить про це історія. Отже, чи віднесемо ми ці слова до Авессалома і його союзників, чи до когось іншого, чи, нарешті, до самого Саула, істина не зазнає від цього жодної шкоди. Слово «відплата» тут ужито в невласному значенні, замість слова «віддача»; бо давання — це, власне, початок благодіяння чи шкоди, що ми їх комусь чинимо, віддача ж — це співмірна з отриманим добром чи шкодою відплата за це, а відплата — нове, повторне воздаяння добром чи злом з боку тих, хто дає; це ніби відплата на відплату. Слово «відплата» в Писанні, а надто в псалмоспівця, трапляється дуже часто."],"h":"Господи, Боже мій, якщо я вчинив це, якщо є неправда в руках моїх, якщо я відплатив тим, хто віддає мені злом, — то хай упаду від ворогів моїх порожнім"},{"v":"6","t":["Хай переслідує, каже, Авессалом душу мою, тобто мене самого, і хай заволодіє ним."],"h":"Хай же переслідує ворог душу мою, і хай наздожене"},{"v":"6","t":["Під життям тут слід розуміти кров, бо вона теж є причиною життя, як найважливіший з чотирьох первнів, з яких складається жива істота."],"h":"І втопче в землю життя моє"},{"v":"6","t":["Славою пророк називає тут своє славне й усіма дуже шановане тіло, шановане за силу й за ту велич, якої надавав йому царський сан. «Оселить у порох» означає повалити його (тобто тіло) на землю й обернути на порох. Наведені вище слова можна також відносити й до ворога невидимого, диявола; у них ніби виражене бажання пророка, щоб його гнав ворог і щоб він був опанований, не маючи більше сили тікати від його нападів, — щоб було втоптане в землю, тобто в земні справи, саме життя його. Це саме виражає слово «втоптати», коли ворог нарешті ніби наступає своїми ногами на переможеного і зухвало топче його, що лежить. І не саме тіло зазнає при цьому страждання, а й слава, тобто сам розум, бо він — слава й честь нашої душі; пророк висловлює бажання, щоб розум був відтягнутий до землі, щоб він просто прилип до земних речей, аби через це вже не міг більше линути до Бога на крилах споглядання."],"h":"І славу мою в порох оселить"},{"v":"7","t":["Господь устає іноді й не в гніві, як свідчить Писання. «Воскресни, Господи, — каже той самий пророк в іншому місці, — спаси мене, Боже мій» (Пс. 3:8); але тут пророк прикликає Господа до відплати. Як сидіння в Бога ми розуміємо не тілесно, а духовно, так само не тілесно слід розуміти й уставання в Бога. Сидіння Боже власне означає Його царську велич, гідність Судді і Його міць; уставання ж означає вставання для покарання й заступництва за гідних цього. Так само й гнів у Бозі слід розуміти не як гнівну пристрасть, а як покарання тих, хто на нього заслужив."],"h":"Воскресни, Господи, в гніві Твоєму"},{"v":"7","t":["Ти, каже, Господи, великий, явися й покажи Себе таким людям. А явиш Ти Себе таким «на межах», тобто в умертвінні Твоїх ворогів, бо смерть становить кінець життя кожного. Вороги ж Твої — ті, хто водночас і мої вороги, як ті, що переступили Твої повеління."],"h":"Піднесися на межах ворогів Твоїх"},{"v":"7","t":["Хай не терпиш Ти довше, каже пророк, а хай покажеш винуватця порушення того Твого повеління, яке Ти оголосив через Мойсея і яке читається так: «Шануй батька твого і матір твою». А мій власний син запалав гнівом проти свого батька. Цьому місцю можна надати й такого змісту, що пророк тут виливає перед Богом свої моління щодо таїни воскресіння. За свідченням Євангелія, Господь саме казав юдеям про Своє тіло таке: «Зруйнуйте цей храм, і за три дні Я поставлю його» (Ін. 2:19). Отже, встань, каже, заради Твого повеління, яке Ти пояснив юдеям, сказавши: «Зруйнуйте», — і вони зруйнують."],"h":"І встань, Господи Боже мій, за повелінням, яке Ти заповідав"},{"v":"8","t":["Якщо тільки явиш Ти мені Свою допомогу, то багато хто, побачивши це, злякається й навернеться до Господа. Вислів «оточить Тебе» означає тут те саме, що «обійдуть», тобто обертатимуться довкола Твоїх повелінь, ніколи не відпадаючи від них, бо Бог є Бог безмежного. Але цей вислів так само може бути віднесений і до воскресіння Ісуса Христа. Бо тоді довкола Христа було зібрання народів з усіх кінців землі, що утворювали ніби своєрідне коло довкола Нього. Або також: «оточить Тебе», інакше кажучи: прославить і оспіває Тебе в гімнах; гімни ж Богові ми справді звичайно співаємо не поодинці, а цілим хором (зібраннями). І так тут під відомою формою, що належить до цієї дії, зображуватиметься сама дія."],"h":"І зібрання людей оточить Тебе"},{"v":"8","t":["Заради, кажу, цього зібрання народів зійди Ти, о Примирителю наш, до Отця Твого і повернися на висоту тієї слави, яку Ти мав перш буття світу, — зійди, коли звершиш Ти нарешті невимовну таїну нашого спасіння."],"h":"І заради нього на висоту повернися"},{"v":"9","t":["Не залишить, каже, Господь без уваги того, що було вчинено проти мене моїми ворогами, а все розсудить. Або також: «судить», судитиме, з одного боку засуджуючи нечестивих, з другого — ставлячи праведників праворуч Себе. «Суди мене, Господи, за правдою моєю і за незлобивістю моєю, що в мені». Згадавши про суд Божий, пророк одразу ж додає: будь, каже, Господи, і мені Суддею, напруж для цього навіть останні Твої сили, і випробуй, каже, мою праву справу, яку я обстоював проти батьковбивці Авессалома та його однодумців; зроби це, далі, для мене за моє щиросердя. Але чому пророк, тоді як в одному місці каже: «Не входь у суд з рабом Твоїм» (Пс. 142:2), тут, навпаки, висловлює особливе бажання бути судженим? Там він ніби так каже, звертаючись до Господа: не судися Ти, Боже, зі мною і не зіставляй моїх діянь з отриманими мною від Твоєї благості дарами; тут же він просить Бога розсудити його з іншими, саме з тими, хто чинив із ним несправедливо й шукав його загибелі."],"h":"Господь судитиме людей"},{"v":"10","t":["Так, якби, каже, колись припинилося лукавство грішників, то праведники йшли б уперед прямо, тобто безперешкодно проходили б тоді путь чесноти. «Той, Хто випробовує серця й нирки, Боже праведний». Ти, каже, Боже, Який праведно досліджуєш серця й нирки наші, тобто власне те, що становить плоди гніву, і те, що становить корінь наших пожадань, бо серце наше слугує оселею гніву, а нутрощі наші становлять джерело наших пожадань, а те й те разом породжує гріх. Або інакше: Бог випробовує й досліджує наше серце й нутрощі. Вислів же «праведно» в такому разі краще розглядати вже в зв’язку з наступними словами: «допомога моя від Бога, що спасає правих серцем»."],"h":"Хай скінчиться злоба грішних, і Ти направиш праведного"},{"v":"11","t":["Будучи правим і простим серцем і намагаючись спрямовувати себе правою путтю чесноти, я, каже, очікую собі допомоги — не людської, яка марна, а допомоги від Бога, Який може спасти мене."],"h":"Допомога моя від Бога, що спасає правих серцем"},{"v":"12","t":["Ці слова пророк, здається, спрямовує проти тих, хто спокушався щодо промислу Божого, питаючи себе: чому він допустив синові повстати на свого батька? Отже, «праведний» означає того, хто співмірює Свою відплату з діяннями; «сильний», інакше кажучи, такий, що може все, чого лише захоче; «довготерпеливий» же той, хто не одразу посилає покарання на винних."],"h":"Бог — Суддя праведний, і сильний, і довготерпеливий"},{"v":"12","t":["Це пророк додав, щоб пояснити, у чому саме полягає суть Божого довготерпіння. Тоді як ми, грішачи щодня, щохвилини стаємо гідними Божого покарання, Сам тим часом Господь наш, довготерплячи нас, щоразу дає нам час на покаяння. Під «гнівом» тут слід розуміти покарання, що спіткає грішників. Деякі не розуміють, як Бог, будучи праведним і справедливо караючи грішників, може водночас бути й людинолюбним? На це відповімо: праведний Він — як той, хто віддає кожному гідне; людинолюбний же — як той, хто не одразу піддає нас заслуженому покаранню, а терпить нас і дає нам час для нашого навернення на путь чесноти, як той, хто не дозволяє нашому ворогові діяти проти нас за його злою волею, і всіма способами піклується про наше спасіння."],"h":"І не наводить гніву щодня"},{"v":"13","t":["Пророк, передбачаючи, що його псалми будуть у руках і в устах людей усіх станів, користується деякими доречними порівняннями, узятими й з військової справи. Якщо, каже він, ви, що ухилилися з путі правої на путь гріха й прилипли до речового, не повернетеся знову до Бога, то ви не уникнете за це покарання. «Меч» означає тут гіркоту, а «лук» — швидкість смерті, що спіткає нерозкаяного. Далі гостріння зброї й натягування лука вказують на готовність покарання, що має нас спіткати, і водночас на довготерпіння Боже до нас. Приготування лука («приготував його») вказує на близькість удару, який, якщо ще не досяг винного, то лише завдяки тому, що Бог спрямував його на нього слабше, ніж належало. Або: гостріння зброї означає сильний ступінь покарання, натягування ж лука — його близькість; готовність лука до удару вказує на готовність покарання, якби тільки ми вчасно не покаялися."],"h":"Якщо ж не навернетеся, меч Свій нагострить, лук Свій натягнув і приготував його"},{"v":"14","t":["Під цим образом покарання через стріляння з лука слід розуміти взагалі найрізноманітніші види смерті — як-от смерть від меча, смерть від вогню, від води, від землетрусу, від поглинення землею, від різних хвороб. Усе це — знаряддя смерті, через які вона збирає свою данину. Слід зауважити, що хоч тут і вживається людська мова, але її слід розуміти гідно величі Божої. Якщо ж пророк уживає тут вислови грубі й матеріальні, то робить це лише для того, щоб його мова могла бути зрозумілою для слухачів. Пророк узагалі нерідко користується у своїх псалмах подібними грубими висловами, поблажливо зважаючи на недоумство своїх слухачів. Саме з цієї причини він і зображує Бога ніби з мечем у руках, з луком, стрілами й іншим військовим знаряддям, що гострить Свою зброю, натягує лук; зображує з тією метою, щоб збільшити цим страх у слухачах і тим успішніше подіяти знайомими їм назвами зброї на їхню скам’янілу душу. Звісно, не потребує подібної зброї Той, від одного погляду Якого тремтить земля, у руці Якого всяке дихання, Хто розсипає гори Своєю міццю й чинить усе інше, що передали нам про Його невимовну могутність учителі богопізнання."],"h":"І на ньому приготував знаряддя смерті"},{"v":"14","t":["Тут пророк підбадьорює праведників. Покарання Божі, каже він, приготовані власне для нечестивих. «Тими, що горять», він називає тут тих, хто цілковито позбавлений вологи добрих діл і хто вже настільки висох для вправляння в добрі, що став легкозаймистим від вогню покарання; їх навіть можна назвати покараними, тобто ніби вже сущими у вогні покарання, бо воно неодмінно їх чекає. Або також «тими, що горять», інакше кажучи — тими, хто горить у вогні пристрастей, гніву, плотських пожадань, користолюбства тощо. Зобразивши так вище різноманітний гнів Божий і погрожуючи цим гнівом людям нечестивим, далі пророк дає нам деякі настанови, узяті ним з теперішніх речей, а потім звертає свою мову до Авессалома."],"h":"Стріли Свої для тих, що горять, приготував"},{"v":"15","t":["Цей зрадник, тобто Авессалом, став, каже, вагітним неправдою, беззаконно задумавши вигнати мене з даного мені Богом мого царства. Назву родових болів пророк ужив тут, щоб показати, яку велику скорботу й які муки терплять ті, хто намагається заподіяти кривду своєму ближньому. Такі люди сповнюються досадою; вони буквально розриваються від гніву, оскверняються помислами, блукають безліччю стежок неправди, зазнають страху, душевного томління і доти не звільняються від цих своїх внутрішніх бичів, доки не вдається їм здійснити задумане на ділі. Але й після того вони все-таки ще не вільні від осуду власного сумління. Тому, коли Писання хоче показати якусь особливо тяжку скорботу, воно іноді називає таку скорботу муками родів. Грецька назва цього роду муки — ὀδύνη — походить від дієслова οἰδαίνειν, що означає власне «набрякати», або збільшуватися в обсязі. Коли плід в утробі матері цілком готовий, тобто остаточно сформувався, тоді він уже не може довше в ній залишатися і прямує до виходу на світ, завдаючи при цьому найтяжчих болів породіллі. Це порівняння моральних болів, яких ми зазнаємо тоді, коли народжуємо неправду, з фізичними болями породіллі вказує на те, що зло не вроджене нашій природі, а прищеплюється нам ззовні, потім воно в нас дозріває і, нарешті, завдає нам найтяжчих мук, подібних до мук породіллі."],"h":"Ось він заболів неправдою"},{"v":"15","t":["У родах найперше звичайно буває зачаття, потім уже муки родів, коли плід остаточно дозрів. Вище говорилося про зачаття, про саме народження й про муки родів разом, водночас; тут же говориться окремо про ці моменти народження. Так, Авессалом, народивши в муках неправду, услід за тим тяжко занедужав від неї з пояснених вище причин, а також тому, що не знаходив ще поки слушної нагоди здійснити задумане беззаконня, і зачав знову — уже недугу, тобто дістав недугу тілесну; бо коли душа наша втомлена, то нам при цьому зраджують і наші тілесні сили. Отже, Авессалом не лише зазнавав скорботи в душі, а й терпів тілесні страждання, доки нарешті не породив свого беззаконня, що полягало по суті в неповазі до свого батька, у спрямованому проти нього гонінні й у зневаженні його наложниць. Деякі, тримаючись коротшого тлумачення наведеного місця, розуміють тут під муками родів побудову в голові Авессалома плану заколоту проти батька, а під зачаттям — сам заколот. Або також: хоч Авессалом довго й тяжко мучився в душі й багато вистраждав від свого підступного задуму, він усе-таки не міг заспокоїтися й тепер, після стількох мук; тому від однієї й тієї самої причини він дістав нову скорботу, яка була для нього новою, такою ж, як і попередня, недугою і ніби повторними муками родів."],"h":"Зачав біль і породив беззаконня"},{"v":"16","t":["Він готував, каже, мені небезпеку, і таку небезпеку, від якої я ледве міг урятуватися, що саме й виражено в уподібненні цієї небезпеки ровові. Як із рову вже не може втекти той, хто в нього потрапив, особливо якщо рів цей «викопаний», тобто подвійно поглиблений, — так і та небезпека, яку готував для мене батьковбивця, мій син, має з одного боку глибину підступу, з другого — оточена смертельним колом. Але він сам потрапить у цю небезпеку на покарання за те, що хотів упіймати в неї мене."],"h":"Рів вирив, і викопав його, і впаде в яму, яку зробив"},{"v":"17","t":["І те, і те, каже, спіткає його самого. Авессалом справді був ніби поглинутий небезпекою, і його підступ обернувся на його ж голову. Підбадьорюючи ряди свого війська під час битви й проїжджаючи верхи під гілками одного дерева, він заплутався в них своїм волоссям і повис на них, де незабаром і помер у страшних муках."],"h":"Повернеться біль його на голову його"},{"v":"17","t":["Та неправда, яку він сам спрямовував проти інших, вразить його самого, і вразить смертельно в саме тім’я. Саме так і сталося насправді. Почавши бій проти свого батька з наміром погубити його, сам він (Авессалом) замість того став жертвою цієї війни."],"h":"І на тім’я його неправда його зійде"},{"v":"18","t":["Тепер же, коли битва закінчилася так, я віддам, каже, подяку Богові за Його праведний суд."],"h":"Визнаватиму Господа за правдою Його"},{"v":"18","t":["Я співатиму, каже, імені Його на подяку за даровану мені перемогу; бо я прикликав ім’я Його, і Він допоміг мені. А якщо й ім’я Його має таку могутність, то хто ж не побоїться Самого Господа «Всевишнього», інакше кажучи — Того, Хто вищий за все, Хто над усіма, вище небес? Зауважимо, що наведені вище слова — не мова людини, яка радіє з чужої поразки, а тим більше з пролитої крові власного сина; інакше пророк тріумфував би, а не сумував би в день перемоги. Ні. Це мова мужа, що приймає те, що сталося, як Божий жереб, як праведне Боже покарання, яке спіткало підступних. Деякі тлумачі слова «рів вирив» і наступні, аж до слів «неправда його зійде» (Пс. 7:17), пояснюють значно простіше. Це місце, кажуть вони, має метафоричний зміст. Тут, на їхню думку, пророк ніби так каже: усе те, що замишляв проти мене Авессалом, він зазнає на собі самому. Ці слова можуть служити нам як вираз наших почуттів щодо нашого ворога — диявола."],"h":"І співатиму імені Господа Всевишнього"}],"8":[{"v":"1","t":["Що саме означає вислів «на кінець», про це вже говорилося в попередніх наших міркуваннях. Далі «точилами» пророк називає тут храми Божі, розсіяні всюди по вселенній. Бо Господь Ісус Христос — виноградна лоза, як Він Сам називає Себе в Євангелії (Ін. 15:5), Його апостоли — гілки на цій лозі, віра ж християнська — виноградне гроно, яке, вичавлюване в церквах, ніби в точилах, дає з себе вино християнського вчення, що звеселяє серця віруючих. Отже, пророк оспівав цей псалом від імені цих духовних точил, тобто від імені християнських церков. За давніх, старозавітних часів було збудовано лише один храм істинному Богові, що містився в одному тільки Єрусалимі; бо тільки одному народові загалом було дано від Бога в уділ те, про що говорить пророк Ісая такими висловами: «І збудував башту, і викопав у ньому точило» (Іс. 5:2). «Баштою» він називає саме Єрусалимський храм, а «точилом» — влаштований у цьому храмі жертовник. Але наприкінці часів, а також з кінцем самого того богослужіння, цей храм було зруйновано, а замість нього по всьому лицю землі постали в незліченній кількості Христові церкви, бо всі народи знову дістали тоді втрачене ними колись істинне пізнання про Бога."],"h":"На кінець, про точила, псалом Давида"},{"v":"2","t":["Ісус Христос — Господь не лише віруючих, а й невіруючих; тільки Господом невіруючих Він може бути названий єдино як їхній Творець, для віруючих же Він Господь подвійно — і як їхній Творець, і як Бог; тому й ім’я Господа в наведеному вище місці повторено двічі. Це вигукують церкви віруючих, звертаючись зі своїми словами до Ісуса Христа: о Господи, ніби так кажуть вони, Творче наш! О Господи наш, Ти, Кого ми так недавно пізнали як Господа! — Вельми «дивне ім’я Твоє по всій землі!» Саме прикликання цього імені відганяє демонів, воскрешає мертвих, віддаляє хвороби, змінює стихії й має владу над усім. Тут ім’я Господнє назване дивним; але в іншому місці пророк називає ім’я Господнє також страшним. Отже, дивне ім’я Господнє через ті надприродні дії, якими супроводжується його прикликання, а страшне — через невимовну могутність, що виявляється в цих діях. Зверніть увагу на те, як пророк Давид, назвавши Господа Господом «нашим», зарахував до нас і самого себе, без сумніву передбачаючи таїну майбутнього й ту спасенну віру в Розіп’ятого, яка згодом охопила всі кінці світу. Але чим виправдаються самі юдеї в тому, що ім’я Бога Вседержителя колись було в нехтуванні в більшості народів, і до того ж у нехтуванні саме з тієї причини, як каже Сам Бог через пророка Ісаю, що «ім’я» Його «через них» (тобто через юдеїв) «зневажалося серед народів» (Іс. 52:5)! Звідси, між іншим, стає очевидним, що сказані вище слова, де говориться, що ім’я Господнє дивне «по всій землі», без жодного сумніву стосуються християнського часу."],"h":"Господи, Господь наш, яке дивне ім’я Твоє по всій землі!"},{"v":"2","t":["Величчю пророк називає тут вочоловічення Боже, яке й справді сповнене величі, що перевищує всякий розум. Ця сама велич піднеслася, каже він, понад самі небесні сили, як незбагненна для них і дивовижна. І дивуються такому Божому таїнству не лише люди, а й самі ангели небесні. Або інакше: пророк, бажаючи показати нам безмежну могутність божественної природи, каже: піднеслася велич Твоя вище небес, бо земля не могла вмістити цієї величі. Про що інший пророк говорить такими висловами: «Покрила небеса велич Його, і хвали Його повна земля» (Авв. 3:3)."],"h":"Бо піднеслася велич Твоя вище небес"},{"v":"3","t":["Пророк провіщає тут хвалебну пісню дітей, оспівану колись ними на честь Господа. З усіх чудес і знамень, які вчинив Ісус Христос на землі, він указує тільки на здивування дітей при вигляді втіленого Бога, що виявилося в хвалебній пісні, указує на це одне як на особливо разюче чудо. І справді, адже випадки воскресіння, наприклад, мертвих бували й до Христа, бували також і випадки зцілення прокажених і вигнання бісів; але хор немовлят, що голосно й виразно співали славу Божу, уперше пролунав на землі лише тоді. До того ж ті, що співали, були не просто діти, а, як каже пророк, діти, що ще ссуть молоко, тобто немовлята, а це явище надзвичайне найвищою мірою. «Вчинив» же, інакше кажучи: улаштував так, що ця хвалебна пісня, власне, лунала з уст ангелів, бо мова самих дітей була ще не зовсім виразна."],"h":"З уст немовлят і ссущих Ти вчинив хвалу"},{"v":"3","t":["Пророк пояснює навіть саму причину цього чуда. Це, каже, було зроблено, Господи, заради злобних ворогів Твоїх, тобто юдеїв, які підозріло дивилися на інші Твої чудеса, думаючи, чи не «обманюєш» Ти якимсь чином їхні очі; а в оспіваній Тобі пісні немовлят, які були власними дітьми Твоїх ворогів і весь час росли при них, усяка подібна підозра зовсім не могла мати місця. Отже, це чудо було спрямоване на те, щоб знищити підозріливість юдейського народу щодо Христа, тобто осоромити цей народ — ворога й водночас месника Божого. Ворогом названо тут юдейський народ як такий, що ворогує проти Сина Божого; месником же — як такий, що прикриває свої ворожі спонуки й дії іменем Бога Отця. Але під ворогом і месником можна розуміти тут також і диявола. Він також ворог Божий, бо противиться заповідям Божим і ворогує проти друзів Божих; він водночас і месник Божий, бо після відпадіння когось від Бога намагається втримати відпалого в такому стані і, крім того, спрямовуючи до переступу заповідей Божих, піддає його покаранню, або відплаті, з боку Бога. Тоді і цей ворог і месник Божий так само був осоромлений і знищений хвалебною піснею немовлят. Слід зауважити, що пророк описує подію, про яку тут ідеться, не як таку, що має статися, а як уже звершену, бо він споглядав своїми пророчими очима далеке від нього майбутнє ясно, ніби те, що вже сталося. А може, й ці слова, як і наведені вище, пророк вимовив також від імені церков; це ніби слова, які вони колись мали вимовляти."],"h":"Заради ворогів Твоїх, щоб знищити ворога й месника"},{"v":"4","t":["Колись язичники думали, що світ створили їхні неправдиві боги; але ось істина осяяла цей темний язичницький світ своїм яскравим світлом, і Церква віруючих вигукує тепер так: Боже, я пізнаю небеса як «діла пальців Твоїх»! «Небесами» пророк називає тут небо, створене на початку й під час самого творення ще не мало на собі світил, і небесну твердь з її незліченними світилами, що з’являються в історії творення з четвертого дня. А може, тут ужито множину замість однини, тобто сказано «небеса» замість «небо», за властивістю єврейської мови. Говорячи про небо, яке ніби огортає собою весь видимий нам світ, пророк хотів указати цим самим і на небо, і водночас на все створене, оточене звідусіль небесним склепінням. «Діла пальців Твоїх». Це, на думку деяких тлумачів, сказано для того, щоб показати, що навіть такі важливі й величні частини творіння, як, наприклад, небо, не вимагали від свого Творця якихось особливих зусиль, а становлять вияв найзвичайнішої Його творчої всемогутності; це лише діла Його пальців, не більше. На мою ж думку, пророк ужив тут ці слова без різниці, тобто не надаючи їм якогось особливого значення, подібного до наведеного вище; бо в іншому, наприклад, місці він каже: «І діла рук» (рук, а не пальців, як у цьому псалмі) «Твоїх — небеса» (Пс. 101:26). «Місяць і зорі, які Ти заснував». Згадавши про небо, пророк додає кілька слів і про оздобу неба. Я пізнаю, ніби так каже він, Тебе як Творця не тільки неба, а й небесних зір. Згадуючи ж про місяць, пророк, як можна думати, мав при цьому на увазі також і сонце, і, говорячи про перший, указує тим самим і на друге; бо відомо, що місяць сам дістає своє світло від сонця і так стає видимим для нас, тому обидва ці світила у свідомості людей завжди постають у зв’язку одне з одним. Відомо, що ці два великі світила такі, що коли згадуєш одне, то у твоїй свідомості неодмінно одразу ж відтворюється уявлення й про друге. Так, навпаки, в іншому місці пророк згадує тільки про сонце, кажучи: «Ти вчинив зорю і сонце» (Пс. 73:16), а так само, звісно, й місяць, бо обидва ці великі світила взаємно одне одного передбачають. Далі: «які», тобто зорі або ж узагалі діла. «Заснував», інакше кажучи: утвердив, міцно закріпив, так що вони ніколи не можуть залишити своїх місць, хоча й не мають під собою жодної твердої основи й видаються ніби такими, що висять у повітряному просторі."],"h":"Бо побачу небеса — діла пальців Твоїх"},{"v":"5","t":["Це також з приводу вочоловічення Бога сказав пророк, що наперед пізнав таїну цієї події. Що таке людина, — ніби так каже він, — що Ти шукаєш її, Боже, Своїм милосердям, це неслухняне створіння Твоє, що забуває про Твоє над ним владарювання? Тут мова невласна, метафорична, а цю метафору пророк запозичив у тих людей, які, постаравшись забути когось, згодом, через деякий час, рухомі співчуттям до забутої ними особи, знову воскрешають у собі спогад про неї; цього мало — вони навіть намагаються допомогти їй, у чому треба, і захистити її. Ось це саме й означає те відвідання, про яке говориться вище в слові «відвідуєш». Бо не ангел і не посередник, а Сам Господь прийшов, щоб спасти нас. Але що ж таке справді людина, що заради неї мало це статися? Чому, коли впали ангели, Ти, Боже, нічого подібного не зробив для них, а ось падає людина — і Ти Сам раптом приходиш на допомогу нашій немочі? Слова «людина» і «син людський» — відповідні один одному вислови, що означають те саме. Подібний спосіб висловлювання властивий Старому Завітові. «Син людський» тут, здається, власне перифраз слова «людина»."],"h":"Що є людина, що Ти пам’ятаєш її, або син людський, що Ти відвідуєш його?"},{"v":"6","t":["Пророк згадав про давні благодіяння Божі, даровані Богом першій людині на землі при її творенні. Бо, вийшовши на світ із рук Творця, перша людина мала такі досконалості природи, що лише чимсь незначним була применшена перед ангелами Божими — через дароване їй тіло, а з ним усе те, що стосується тіла. А це було зроблено, звісно, не без особливого Божого промислу щодо неї, щоб, коли вона загордиться своїм розумом, водночас могла смирятися своєю земною природою. Бо якщо, навіть обтяжені тілом, ми пишаємося своїм розумом, то що було б із нами, якби ми не мали тіла?"],"h":"Ти применшив його трохи перед ангелами"},{"v":"6","t":["Ти увінчав, каже пророк, славою людину, створив її за Своїм образом і подобою; увінчав далі честю, даровавши їй владу над усіма тваринами."],"h":"Славою і честю увінчав його"},{"v":"7","t":["Нарешті Ти поставив, каже, її царем над усіма створіннями, сказавши нашим прабатькам: «Плодіться і розмножуйтеся, і наповнюйте землю, і володійте нею» (Бут. 1:28)."],"h":"І поставив його над ділами рук Твоїх"},{"v":"7-8","t":["Ці слова, як і попередні, запозичено з книги Буття. «І пануйте над рибами морськими, — говориться там, — і над птахами небесними, і над усією худобою, і над усією землею» (Бут. 1:28). Сказавши, що все підкорив Творець під ноги людини, пророк починає далі перелічувати частинами це підкорене, згадує найперше про найбільш приручених людиною тварин — овець. Худобою польовою звичайно називаються всі ті чотириногі, що пасуться на полях; худоба ж — це всяке чотириноге, що має голову, нахилену вперед і донизу. Під худобою (сказано «худобу» в множині) пророк, без сумніву, розумів узагалі всіх тварин, що живуть на суходолі, як свійських, так і диких; бо всі вони були віддані Творцем на службу людині, і вона мала б владу над усіма й досі, якби зберегла колишню гідність душі. Птахи небесні — інакше кажучи, птахи повітряні; пророк ужив тут назву неба в невласному значенні замість повітря, що нерідко трапляється й у нас, бо повітря видається нам розлитим над нашими головами подібно до небесного склепіння. Звернувши потім свою увагу на всю безліч риб, пророк хоче охопити все це безмежне розмаїття кількома словами, сказавши: «що ходять стежками морськими», — уживаючи замість чоловічого роду середній, він, без сумніву, мав на меті вказати цим на різні роди риб. Ми тлумачимо так цей псалом щодо простої, звичайної людини. Утім, за перенесенням його можна пояснювати й щодо людської природи Ісуса Христа, як розуміє апостол Павло в своєму посланні до євреїв. Що таке, ніби так каже пророк, людська природа, прийнята на Себе Богом Словом, щоб пам’ятати про неї, кажучи: «Це Син Мій улюблений» (Мф. 3:17)? Сином же людським пророк назвав Ісуса Христа для того, щоб спростувати вчення тих, хто думає, що Христос приніс разом із Собою на землю Свою плоть згори. З тієї самої, звісно, причини й Сам Господь нерідко в Євангеліях називає Себе Сином Людським, даючи цим зрозуміти, що Він приготував Собі храм, тобто тілесний склад, з дівочої й чистої крові Богородиці. А хто народився від жінки, той по справедливості й називається сином людським, бо й жінка — людина. Відвідав же його, бо «бачив я, — каже, — Господа перед собою повсякчас, бо Він праворуч мене» (Пс. 15:8). «Применшив його трохи перед ангелами» сказано тому, що Ісус Христос зазнавав і спраги, і голоду, і переносив справжні тілесні страждання. «Увінчав його», тобто прикрасив: славою, тобто божеством, «честю», інакше кажучи, перевагою над ангелами, тому вони нерідко Йому служили; або також «честю» вказує на те найменування Ісуса Христа Богом, яке присвоюють Йому віруючі, і на те богошанування, яке вони Йому віддають. «Усе підкорив» — як новому Адамові, що зберіг у собі неушкодженими образ і подобу Божу. Далі «вівці» — це, за перенесенням, ті язичники, що увірували в Христа, яких Він розшукав, коли вони до Нього блукали по різних горах і пагорбах, і зібрав їх у Свою кошару. Воли ж — це юдеї, що несли на собі тяжке ярмо Мойсеєвого закону. «А худоба польова» — це ті, хто, не прийнявши ні закону Мойсеєвого, ні закону благодаті, а служачи ідолам і блукаючи рівнинами й низинами теперішнього життя, не можуть піднятися на висоту споглядання. «Птахи небесні» — це ангели; «риби ж морські» — це демони, які, подібно до риби, вистрибують над хвилями теперішнього життя й живляться гіркотою й солоністю наших нечистих діянь. Усе підкориться нарешті Ісусові Христу, бо Йому колись поклониться всяке коліно небесних, і земних, і підземних. Не зайвим, гадаємо, буде запропонувати ще одне пояснення слів «применшив його» тощо. А саме, що применшив, зрозуміло, не перед ангелами, а перед славою Бога Отця. І тоді це місце слід розуміти так: Ти, Боже, Отче Господа нашого Ісуса Христа за божеством, «применшив Його трохи» перед Твоєю гідністю — через Його плотську природу. Дальші слова в такому разі слід читати вже так: над ангелами «славою і честю увінчав Ти Його», тобто більше за кожного ангела. Бо ніхто з ангелів не дістав ні імені Божого, ні таких служителів, як Христос."],"h":"Усе підкорив Ти під ноги його: овець і волів усіх, ще й худобу польову, птахів небесних і риб морських, що ходять стежками морськими"},{"v":"10","t":["Оскільки цей псалом пророкує про таїну втілення Ісуса Христа, і Сам Христос зійшов на землю з неба, а потім знову зійшов на небо, звершив ніби певну навколосвітню подорож і повернувся до Своєї колишньої Отчої слави, — тому й сам цей псалом є ніби щось, що обертається довкола однієї думки. Тож чим він починається, тим і закінчується: як починає, так і закінчує його пророк саме висловом здивування перед величчю імені Божого."],"h":"Господи, Господь наш, яке дивне ім’я Твоє по всій землі!"}]};
